_SOURCES = {
    'shared': (True, '"""Python reference definitions shared by the tools and the bot (BUILDMAP §3, §4, §5)."""\n'),
    'shared.cards': (False, '"""Cards, colex combination indices and the preflop canonical table (BUILDMAP §4.1, §4.2, §5.1.1)."""\nimport itertools\nfrom math import comb\n\nimport numpy as np\n\nRANKS = "23456789TJQKA"\nSUITS = "shdc"              # the engine\'s SUITS order\n\nN2 = comb(52, 2)            # 1,326\nN3 = comb(52, 3)            # 22,100\nN4 = comb(52, 4)            # 270,725\nN_PRE = 1755                # canonical 3-card classes\n\n# ---------------------------------------------------------------- §4.1 card ids\n\ndef rank(c):\n    return c >> 2\n\n\ndef suit(c):\n    return c & 3\n\n\ndef parse_card(s):\n    """"As" -> 48, "2c" -> 3. Raises ValueError on anything else."""\n    if not isinstance(s, str) or len(s) != 2 or s[0] not in RANKS or s[1] not in SUITS:\n        raise ValueError(f"bad card: {s!r}")\n    return RANKS.index(s[0]) * 4 + SUITS.index(s[1])\n\n\ndef format_card(c):\n    return RANKS[c >> 2] + SUITS[c & 3]\n\n\ndef parse_cards(xs):\n    return [parse_card(s) for s in xs]\n\n\ndef format_cards(cs):\n    return [format_card(int(c)) for c in cs]\n\n\n# ---------------------------------------------------------------- §4.2 colex indices\n# Arguments may come in any order; they are sorted ascending first.\n\ndef idx2(a, b):\n    if a > b:\n        a, b = b, a\n    return b * (b - 1) // 2 + a\n\n\ndef idx3(a, b, c):\n    a, b, c = sorted((a, b, c))\n    return comb(c, 3) + comb(b, 2) + a\n\n\ndef idx4(a, b, c, d):\n    a, b, c, d = sorted((a, b, c, d))\n    return comb(d, 4) + comb(c, 3) + comb(b, 2) + a\n\n\ndef _unrank(i, k):\n    """Inverse of the colex index for k cards. Returns an ascending tuple."""\n    out = []\n    top = 52\n    for j in range(k, 0, -1):\n        c = top - 1\n        while comb(c, j) > i:\n            c -= 1\n        out.append(c)\n        i -= comb(c, j)\n        top = c\n    return tuple(reversed(out))\n\n\ndef unrank2(i):\n    return _unrank(i, 2)\n\n\ndef unrank3(i):\n    return _unrank(i, 3)\n\n\ndef unrank4(i):\n    return _unrank(i, 4)\n\n\ndef idx2_array(a, b):\n    """Vectorised idx2 for int arrays (any order within each pair)."""\n    a = np.asarray(a, dtype=np.int64)\n    b = np.asarray(b, dtype=np.int64)\n    lo, hi = np.minimum(a, b), np.maximum(a, b)\n    return hi * (hi - 1) // 2 + lo\n\n\n# COMBO[i] = (a, b), a < b, in idx2 order.\nCOMBO = np.array([(a, b) for b in range(52) for a in range(b)], dtype=np.int64)\n\n# ---------------------------------------------------------------- §5.1.1 CANON3\n\n_SUIT_PERMS = list(itertools.permutations(range(4)))\n\n\ndef canonical_form3(hand):\n    """Smallest, over all 24 suit permutations, of the (rank, permuted suit) pairs sorted descending."""\n    pairs = [(c >> 2, c & 3) for c in hand]\n    return min(tuple(sorted(((r, p[s]) for r, s in pairs), reverse=True)) for p in _SUIT_PERMS)\n\n\ndef build_canon3():\n    """CANON3[idx3] -> canonical class id in [0, 1755), numbered by ascending canonical form."""\n    forms = [canonical_form3(unrank3(i)) for i in range(N3)]\n    ids = {f: n for n, f in enumerate(sorted(set(forms)))}\n    if len(ids) != N_PRE:\n        raise AssertionError(f"expected {N_PRE} canonical classes, got {len(ids)}")\n    return np.array([ids[f] for f in forms], dtype=np.uint16)\n'),
    'shared.evaluator': (False, '"""Numpy hand evaluator (BUILDMAP §4.4, Appendix A).\n\nHand value v = (cat << 26) | (A << 13) | B as int64; higher wins, equal splits.\n`cat` follows the engine\'s HAND_NAMES order (0 high card .. 8 straight flush).\n"""\nimport numpy as np\n\n# ---------------------------------------------------------------- 8192-entry tables\n_M = 1 << 13\nBITS = (1 << np.arange(13)).astype(np.int64)\n_m = np.arange(_M, dtype=np.int64)\n_bits = (_m[:, None] >> np.arange(13)) & 1                   # (_M, 13)\nPOP = _bits.sum(axis=1)\n_from_top = np.cumsum(_bits[:, ::-1], axis=1)[:, ::-1]       # set bits at or above each rank\nTOP = {k: ((_bits * (_from_top <= k)) * BITS).sum(axis=1) for k in (1, 2, 3, 5)}\nST = np.full(_M, -1, np.int64)                               # top rank of best straight, or -1\nfor _t in range(4, 13):\n    _w = 0b11111 << (_t - 4)\n    ST[(_m & _w) == _w] = _t\n_wheel = (1 << 12) | 0b1111\nST[((_m & _wheel) == _wheel) & (ST < 0)] = 3\n\n\ndef _value(cat, a, b):\n    return (np.int64(cat) << 26) | (a << 13) | b\n\n\ndef _finish(rc, sm, rows):\n    """rc: (N,13) rank counts; sm: (N,4) per-suit rank masks."""\n    ranks = (rc > 0).astype(np.int64) @ BITS\n    m2 = (rc >= 2).astype(np.int64) @ BITS\n    m3 = (rc >= 3).astype(np.int64) @ BITS\n    m4 = (rc >= 4).astype(np.int64) @ BITS\n    sc = POP[sm]\n    fs = sc.argmax(axis=1)\n    has_flush = sc[rows, fs] >= 5\n    fmask = np.where(has_flush, sm[rows, fs], 0)\n    sf = np.where(has_flush, ST[fmask], -1)\n    st = ST[ranks]\n    q = TOP[1][m4]; t = TOP[1][m3]; fh_pair = TOP[1][m2 & ~t]; tp = TOP[2][m2]; one = np.int64(1)\n    conds = [sf >= 0, m4 > 0, (m3 > 0) & (fh_pair > 0), has_flush, st >= 0, m3 > 0, POP[m2] >= 2, m2 > 0]\n    vals = [_value(8, one << np.maximum(sf, 0), 0),\n            _value(7, q, TOP[1][ranks & ~q]),\n            _value(6, t, fh_pair),\n            _value(5, TOP[5][fmask], 0),\n            _value(4, one << np.maximum(st, 0), 0),\n            _value(3, t, TOP[2][ranks & ~t]),\n            _value(2, tp, TOP[1][ranks & ~tp]),\n            _value(1, m2, TOP[3][ranks & ~m2])]\n    return np.select(conds, vals, _value(0, TOP[5][ranks], 0))\n\n\ndef evaluate(cards):\n    """cards: int array (N, k) with 5 <= k <= 7. Returns int64 hand values (§4.4)."""\n    cards = np.asarray(cards, dtype=np.int64)\n    N = cards.shape[0]; rows = np.arange(N)\n    rc = np.zeros((N, 13), np.int8); sm = np.zeros((N, 4), np.int64)\n    for j in range(cards.shape[1]):\n        r = cards[:, j] >> 2; s = cards[:, j] & 3\n        rc[rows, r] += 1; sm[rows, s] |= (np.int64(1) << r)\n    return _finish(rc, sm, rows)\n\n\ndef evaluate_board_plus(board, extra):\n    """Fixed board cards + per-row extra cards (N, j). Same values as evaluate()."""\n    extra = np.asarray(extra, dtype=np.int64)\n    N = extra.shape[0]; rows = np.arange(N)\n    brc = np.zeros(13, np.int8); bsm = np.zeros(4, np.int64)\n    for c in board:\n        c = int(c)\n        brc[c >> 2] += 1; bsm[c & 3] |= 1 << (c >> 2)\n    rc = np.tile(brc, (N, 1)); sm = np.tile(bsm, (N, 1))\n    for j in range(extra.shape[1]):\n        r = extra[:, j] >> 2; s = extra[:, j] & 3\n        rc[rows, r] += 1; sm[rows, s] |= (np.int64(1) << r)\n    return _finish(rc, sm, rows)\n'),
    'shared.features': (False, '"""Street features and card buckets (BUILDMAP §4.5, §4.6, §5.1, Appendix A).\n\nPipeline per street: street_rows (evaluate once; callers cache it per hand and street)\n-> own_features (our pairs) or all_features (all 1326 pairs, for range tracking)\n-> buckets via the fitted thresholds.\n\nDead cards (other hole cards, discards) are deliberately ignored here (§4.5).\n"""\nimport hashlib\nimport json\n\nimport numpy as np\n\nfrom .cards import COMBO, idx2\nfrom .evaluator import evaluate_board_plus\n\nN_NEXT_FLOP = 47            # turn cards for a pair on the flop\nN_NEXT_TURN = 46            # river cards for a pair on the turn\nN_CLASS2 = 80\nN_B3 = 400\nN_BT = 200\nN_BR = 100\n\n# ---------------------------------------------------------------- Appendix A: all-hands features\n\ndef street_rows(board, lookahead):\n    """Evaluate every (next card x, pair h) row once per street; reuse for own and all-pairs counts.\n    Groups g are next cards x (turn card on the flop, river card on the turn); the river has one group."""\n    board = [int(c) for c in board]\n    live = np.array([c for c in range(52) if c not in board], dtype=np.int64)\n    nexts = live if lookahead else np.array([-1], dtype=np.int64)\n    G = len(nexts)\n    hidx = np.nonzero(~np.isin(COMBO, board).any(axis=1))[0]\n    gi = np.repeat(np.arange(G), len(hidx)); hi = np.tile(hidx, G)\n    x = nexts[gi]\n    keep = (COMBO[hi, 0] != x) & (COMBO[hi, 1] != x)\n    gi, hi, x = gi[keep], hi[keep], x[keep]\n    extra = np.column_stack([COMBO[hi], x]) if lookahead else COMBO[hi]\n    return dict(G=G, gi=gi, hi=hi, val=evaluate_board_plus(board, extra))\n\n\ndef own_features(rows, pairs):\n    """[(S1, S2)] for each (a, b) in pairs (a < b). Cheap: no sorting."""\n    G, gi, hi, val = rows["G"], rows["gi"], rows["hi"], rows["val"]\n    ca, cb = COMBO[hi, 0], COMBO[hi, 1]\n    out = []\n    for a, b in pairs:\n        h = b * (b - 1) // 2 + a\n        mine = hi == h\n        gv = np.full(G, -1, np.int64); gv[gi[mine]] = val[mine]       # -1: group\'s card hits our pair\n        mv = gv[gi]\n        ok = (mv >= 0) & (ca != a) & (ca != b) & (cb != a) & (cb != b)\n        E = (2 * np.bincount(gi[ok & (val < mv)], minlength=G)\n             + np.bincount(gi[ok & (val == mv)], minlength=G))[gv >= 0].astype(np.int64)\n        out.append((int(E.sum()), int((E * E).sum())))\n    return out\n\n\ndef all_features(rows):\n    """S1, S2 for all 1326 pairs (zero where the pair hits the board). One lexsort + bincounts."""\n    G, gi, hi, val = rows["G"], rows["gi"], rows["hi"], rows["val"]\n    order = np.lexsort((val, gi))                       # by group, then value\n    sv, sg = val[order], gi[order]\n    new = np.ones(len(order), bool); new[1:] = (sv[1:] != sv[:-1]) | (sg[1:] != sg[:-1])\n    dense = np.cumsum(new) - 1                          # global dense id of (group, value)\n    rid = np.empty_like(dense); rid[order] = dense\n    K = int(dense[-1]) + 1\n    first = np.ones(len(order), bool); first[1:] = sg[1:] != sg[:-1]\n    gfirst = np.zeros(G, np.int64); gfirst[sg[first]] = dense[first]\n    cnt = np.bincount(rid, minlength=K); cum = np.cumsum(cnt) - cnt\n    g0 = gfirst[gi]\n    less_tot = cum[rid] - cum[g0]; eq_tot = cnt[rid]\n    a, b = COMBO[hi, 0], COMBO[hi, 1]\n    pc = np.bincount(np.concatenate([a * K + rid, b * K + rid]), minlength=52 * K).reshape(52, K)\n    pcum = np.cumsum(pc, axis=1) - pc                   # per card: hands strictly below\n    W = less_tot - (pcum[a, rid] - pcum[a, g0]) - (pcum[b, rid] - pcum[b, g0])\n    T = eq_tot - pc[a, rid] - pc[b, rid] + 1\n    E = 2 * W + T\n    S1 = np.bincount(hi, weights=E, minlength=1326).astype(np.int64)\n    S2 = np.bincount(hi, weights=(E * E).astype(np.float64), minlength=1326).astype(np.int64)\n    return S1, S2\n\n\ndef street_features(board, lookahead):\n    return all_features(street_rows(board, lookahead))\n\n\n# ---------------------------------------------------------------- thresholds (§5.1.8)\n\nclass Thresholds:\n    """Fitted bucket edges. Built from the exact bytes of data/thresholds.json so the sha matches.\n    (The bot gets these bytes from its embedded blob; it never reads files.)"""\n\n    SHAPES = {"flop_s1": (15,), "flop_v": (16, 4), "gap": (4,),\n              "turn_s1": (39,), "turn_v": (40, 4), "river": (99,)}\n\n    def __init__(self, d, sha):\n        for k, shape in self.SHAPES.items():\n            arr = np.asarray(d[k], dtype=np.int64)\n            if arr.shape != shape:\n                raise ValueError(f"thresholds {k}: shape {arr.shape}, expected {shape}")\n            if (np.diff(arr, axis=-1) < 0).any():\n                raise ValueError(f"thresholds {k}: edges not sorted")\n            setattr(self, k, arr)\n        self.sha = sha\n\n    @classmethod\n    def from_json_bytes(cls, raw, expect_sha=None):\n        sha = hashlib.sha256(raw).hexdigest()\n        if expect_sha is not None and sha != expect_sha:\n            raise ValueError(f"thresholds sha mismatch: {sha} != {expect_sha}")\n        return cls(json.loads(raw), sha)\n\n\n# ---------------------------------------------------------------- bins and buckets (§4.6, §5.1)\n\ndef bin_index(x, edges):\n    """Number of edges <= x (= searchsorted side=\'right\' = std::upper_bound). Scalar or array."""\n    r = np.searchsorted(edges, x, side="right")\n    return int(r) if np.ndim(r) == 0 else r.astype(np.int64)\n\n\ndef flop_v(S1, S2):\n    """V = 47*S2 - S1^2 (int64 / Python int)."""\n    return N_NEXT_FLOP * S2 - S1 * S1\n\n\ndef turn_v(S1, S2):\n    """V = 46*S2 - S1^2."""\n    return N_NEXT_TURN * S2 - S1 * S1\n\n\ndef _two_level(S1, V, s1_edges, v_edges):\n    """s1bin * 5 + vbin, where vbin uses the V edges of that s1bin. Scalar or array."""\n    s1bin = np.searchsorted(s1_edges, S1, side="right")\n    V = np.asarray(V, dtype=np.int64)\n    vbin = (v_edges[s1bin] <= V[..., None]).sum(axis=-1)    # edges sorted -> = upper_bound\n    out = s1bin * 5 + vbin\n    return int(out) if np.ndim(out) == 0 else out.astype(np.int64)\n\n\ndef class2(S1, V, th):\n    """Flop pair class in [0, 80) (§5.1.2)."""\n    return _two_level(S1, V, th.flop_s1, th.flop_v)\n\n\ndef turn_bucket(S1, V, th):\n    """Turn bucket bt in [0, 200) (§5.1.6)."""\n    return _two_level(S1, V, th.turn_s1, th.turn_v)\n\n\ndef river_bucket(E, th):\n    """River bucket br in [0, 100) (§5.1.7)."""\n    return bin_index(E, th.river)\n\n\ndef hand_pairs(hand3):\n    """The three pairs (a < b) of a 3-card hand, in idx2-ascending order."""\n    a, b, c = sorted(int(x) for x in hand3)\n    return [(a, b), (a, c), (b, c)]             # idx2 ascending for a < b < c\n\n\ndef keep_order(hand3, s1):\n    """Pairs in keep-slot order: S1 descending, then idx2 ascending (§5.1.3).\n    s1: S1 of each pair, aligned with hand_pairs(hand3)."""\n    pairs = hand_pairs(hand3)\n    order = sorted(range(3), key=lambda i: (-s1[i], idx2(*pairs[i])))\n    return [pairs[i] for i in order]\n\n\ndef bucket3(hand3, s1, s2, th):\n    """(b3, pairs in keep-slot order) for a 3-card hand on the flop (§5.1.3).\n    s1, s2: features of each pair, aligned with hand_pairs(hand3)."""\n    pairs = hand_pairs(hand3)\n    order = sorted(range(3), key=lambda i: (-s1[i], idx2(*pairs[i])))\n    i0, i1 = order[0], order[1]\n    c2 = class2(s1[i0], flop_v(s1[i0], s2[i0]), th)\n    gapbin = bin_index(s1[i0] - s1[i1], th.gap)\n    return c2 * 5 + gapbin, [pairs[i] for i in order]\n\n\ndef flop_bucket3(rows, hand3, th):\n    """Convenience for the bot: own_features on the cached flop rows -> (b3, slots)."""\n    pairs = hand_pairs(hand3)\n    f = own_features(rows, pairs)\n    return bucket3(hand3, [x[0] for x in f], [x[1] for x in f], th)\n\n\ndef dcls(d, flop):\n    """Discard class (§5.1.5): 0 pairs the flop, 1 overcard, 2 flush card, 3 other."""\n    r, s = d >> 2, d & 3\n    franks = [c >> 2 for c in flop]\n    if r in franks:\n        return 0\n    if r > max(franks):\n        return 1\n    if sum(1 for c in flop if (c & 3) == s) >= 2:\n        return 2\n    return 3\n\n\n# ---------------------------------------------------------------- vectorised variants (range tracking)\n# Inputs are the 1326-long S1/S2 arrays from all_features. Entries for pairs that hit the board\n# are meaningless; callers mask them out.\n\ndef class2_all(S1, S2, th):\n    return class2(S1, flop_v(S1, S2), th)\n\n\ndef turn_bucket_all(S1, S2, th):\n    return turn_bucket(S1, turn_v(S1, S2), th)\n\n\ndef river_bucket_all(E, th):\n    return river_bucket(E, th)\n\n\n_S1_KEY = 1 << 20           # > any S1 (max 47 * 2070 = 97,290)\n\n\ndef bucket3_all(hands3, S1, c2_all, th):\n    """Vectorised bucket3 for many 3-card hands (N, 3) on one flop.\n    Returns b3 (N,) and the idx2 of each hand\'s pairs in keep-slot order (N, 3)."""\n    h = np.sort(np.asarray(hands3, dtype=np.int64), axis=1)\n    a, b, c = h[:, 0], h[:, 1], h[:, 2]\n    p = np.stack([b * (b - 1) // 2 + a, c * (c - 1) // 2 + a, c * (c - 1) // 2 + b], axis=1)\n    s = S1[p]\n    key = (_S1_KEY - s) * 2048 + p              # S1 descending, then idx2 ascending\n    order = np.argsort(key, axis=1)\n    slots = np.take_along_axis(p, order, axis=1)\n    s_sorted = np.take_along_axis(s, order, axis=1)\n    gapbin = np.searchsorted(th.gap, s_sorted[:, 0] - s_sorted[:, 1], side="right")\n    b3 = c2_all[slots[:, 0]] * 5 + gapbin\n    return b3.astype(np.int64), slots\n'),
    'shared.showdown': (False, '"""Weighted showdown on a river board (BUILDMAP §7 Phase 2, §10).\n\nFor each of our hands h, the total range weight of opponent hands that h beats and ties,\nexcluding opponent hands that share a card with h or the board. Same sort + inclusion–exclusion\ntrick as features.all_features, with weights instead of counts. O(n log n), no 1326x1326 matrix.\n"""\nimport numpy as np\n\nfrom .cards import COMBO\nfrom .evaluator import evaluate_board_plus\n\n\ndef river_values(board):\n    """int64[1326] hand values on a 5-card board in idx2 order; -1 where the pair hits the board."""\n    board = [int(c) for c in board]\n    vals = np.full(1326, -1, np.int64)\n    live = ~np.isin(COMBO, board).any(axis=1)\n    vals[live] = evaluate_board_plus(board, COMBO[live])\n    return vals\n\n\ndef weighted_showdown(values, weights, board):\n    """values: int64[1326] (e.g. river_values); weights: float64[1326] opponent range.\n    Returns (beat, tie), float64[1326]: weight of opponent hands that each hand beats / ties.\n    Hands that hit the board get 0, and their weights are ignored."""\n    board = [int(c) for c in board]\n    values = np.asarray(values, dtype=np.int64)\n    weights = np.asarray(weights, dtype=np.float64)\n    live = np.nonzero(~np.isin(COMBO, board).any(axis=1))[0]\n    v = values[live]; w = weights[live]\n    order = np.argsort(v, kind="stable")\n    sv = v[order]\n    new = np.ones(len(sv), bool); new[1:] = sv[1:] != sv[:-1]\n    dense = np.cumsum(new) - 1\n    rid = np.empty_like(dense); rid[order] = dense\n    K = int(dense[-1]) + 1\n    wk = np.bincount(rid, weights=w, minlength=K)\n    below = np.cumsum(wk) - wk                              # weight strictly below each value\n    a, b = COMBO[live, 0], COMBO[live, 1]\n    pc = np.bincount(np.concatenate([a * K + rid, b * K + rid]),\n                     weights=np.concatenate([w, w]), minlength=52 * K).reshape(52, K)\n    pbelow = np.cumsum(pc, axis=1) - pc                     # per card: weight strictly below\n    beat_l = below[rid] - pbelow[a, rid] - pbelow[b, rid]\n    tie_l = wk[rid] - pc[a, rid] - pc[b, rid] + w           # h itself was removed twice\n    beat = np.zeros(1326); tie = np.zeros(1326)\n    beat[live] = np.maximum(beat_l, 0.0)                    # clip float round-off below zero\n    tie[live] = np.maximum(tie_l, 0.0)\n    return beat, tie\n'),
    'shared.betting': (False, '"""Betting abstraction (BUILDMAP §5.2, Appendix B) and an exact port of engine.Hand.betting_round.\n\nTemplates: node dicts {id, kind, bets, facing_allin, actor, slots, child, offset}; actor 0/1 is\nfirst/second to act on the street (preflop: seat = actor; postflop: seat = 1 - actor).\nSeats: 0 = button, 1 = big blind.\n"""\nfrom collections import namedtuple\n\nOPEN, FACING = "OPEN", "FACING"\nEND, FOLD = -1, -2\nSTREETS = ("preflop", "flop", "turn", "river")\nSTARTING_STACK = 200\nSMALL_BLIND = 1\nBIG_BLIND = 2\nMAX_RAISES = 4\nPOT_EDGES = (7, 13, 25, 50, 100)\nSIZE_SLOTS = ("sizeA", "sizeB", "raise")\nSLOT_ACTION = {"fold": "fold", "check": "check", "call": "call",\n               "sizeA": "raise", "sizeB": "raise", "raise": "raise", "allin": "raise"}\n\n\n# ---------------------------------------------------------------- Appendix B: templates\n\ndef build_template(preflop):\n    nodes = []\n\n    def make(kind, bets, facing_allin, actor, is_root):\n        nid = len(nodes); nodes.append(None)\n        can_raise = bets < 4 and not facing_allin\n        if kind == OPEN:\n            slots = ["check"] + (["sizeA", "sizeB", "allin"] if can_raise else [])\n        else:\n            slots = ["fold", "call"] + (["raise", "allin"] if can_raise else [])\n        child = {}\n        for s in slots:\n            if s == "check":\n                child[s] = make(OPEN, bets, False, 1, False) if actor == 0 else END\n            elif s == "fold":\n                child[s] = FOLD\n            elif s == "call":   # the button\'s preflop limp gives the BB its option\n                child[s] = make(OPEN, bets, False, 1, False) if (preflop and is_root) else END\n            else:\n                child[s] = make(FACING, bets + 1, s == "allin", 1 - actor, False)\n        nodes[nid] = dict(id=nid, kind=kind, bets=bets, facing_allin=facing_allin,\n                          actor=actor, slots=slots, child=child)\n        return nid\n    if preflop:\n        make(FACING, 1, False, 0, True)\n    else:\n        make(OPEN, 0, False, 0, True)\n    offset = 0\n    for n in nodes:\n        n["offset"] = offset; offset += len(n["slots"])\n    return nodes, offset\n\n\nPOST, POST_SLOTS = build_template(False)\nPRE, PRE_SLOTS = build_template(True)\nassert (len(POST), POST_SLOTS) == (32, 92)\nassert (len(PRE), PRE_SLOTS) == (19, 54)\n\n\ndef template_for(street):\n    return PRE if street == "preflop" else POST\n\n\ndef seat_of_actor(street, actor):\n    return actor if street == "preflop" else 1 - actor\n\n\n# ---------------------------------------------------------------- §4.6, §5.2.3, §5.2.4\n\ndef round_half_up(x, num, den):\n    """round_half_up(x * num / den) with integer arithmetic."""\n    return (x * num + den // 2) // den\n\n\ndef pot_class(pot):\n    """bin(pot, POT_EDGES) in [0, 6)."""\n    return sum(1 for e in POT_EDGES if e <= pot)\n\n\ndef raw_size(street, node, slot, pot, opp_bet, to_call):\n    """Raise-to amount of a size slot before the min_raise clamp (§5.2.3 table)."""\n    if street == "preflop":\n        if node["kind"] == OPEN:                       # BB after the limp\n            return 6 if slot == "sizeA" else 10\n        if node["bets"] <= 2:                          # open (bets 1) or 3-bet (bets 2)\n            return 3 * opp_bet\n        return round_half_up(opp_bet, 9, 4)            # 4-bet (bets 3)\n    if node["kind"] == OPEN:\n        if street == "flop":\n            return round_half_up(pot, 1, 3) if slot == "sizeA" else round_half_up(pot, 3, 4)\n        return round_half_up(pot, 1, 2) if slot == "sizeA" else pot\n    return opp_bet + pot + to_call                     # postflop pot-size raise\n\n\ndef slot_options(street, node, pot, my_bet, opp_bet, to_call, legal_actions, min_raise, max_raise):\n    """[(slot, legal, amount)] in slot order (§5.2.3). amount is the raise-to amount for size and\n    allin slots when "raise" is legal (size slots after max(amt, min_raise), even if illegal), else None."""\n    can_raise = "raise" in legal_actions\n    out, used = [], []\n    for slot in node["slots"]:\n        if slot in ("fold", "call"):\n            out.append((slot, to_call > 0, None))\n        elif slot == "check":\n            out.append((slot, to_call == 0, None))\n        elif slot == "allin":\n            out.append((slot, can_raise, max_raise if can_raise else None))\n        elif not can_raise:\n            out.append((slot, False, None))\n        else:\n            amt = max(raw_size(street, node, slot, pot, opp_bet, to_call), min_raise)\n            ok = (amt < max_raise\n                  and 20 * (amt - my_bet) < 17 * (max_raise - my_bet)\n                  and amt not in used)\n            if ok:\n                used.append(amt)\n            out.append((slot, ok, amt))\n    return out\n\n\ndef slot_options_req(street, node, req):\n    return slot_options(street, node, req["pot"], req["my_bet"], req["opp_bet"], req["to_call"],\n                        req["legal_actions"], req.get("min_raise"), req.get("max_raise"))\n\n\n# ---------------------------------------------------------------- engine port (chips)\n\nclass StreetState:\n    """Exact port of engine.Hand.betting_round for one street. stacks/committed are the hand\'s\n    lists and are updated in place, as in the engine."""\n\n    def __init__(self, street, stacks, committed, hand=None):\n        self.street = street\n        self.stacks = stacks\n        self.committed = committed\n        self.hand = hand\n        if street == "preflop":\n            self.bets, self.last_raise, self.raises, self.actor = [SMALL_BLIND, BIG_BLIND], BIG_BLIND, 1, 0\n        else:\n            self.bets, self.last_raise, self.raises, self.actor = [0, 0], 0, 0, 1\n        self.acted = [False, False]\n        self.folder = None\n        self.done = 0 in stacks              # someone is all-in: no more betting this hand\n\n    def max_raise(self):\n        a, o = self.actor, 1 - self.actor\n        return min(self.bets[a] + self.stacks[a], self.bets[o] + self.stacks[o])\n\n    def request(self):\n        """The engine\'s action_request fields for the player to act."""\n        a, o = self.actor, 1 - self.actor\n        to_call = self.bets[o] - self.bets[a]\n        max_raise = self.max_raise()\n        legal = ["fold", "call"] if to_call > 0 else ["check"]\n        can_raise = self.raises < MAX_RAISES and max_raise > self.bets[o]\n        if can_raise:\n            legal.append("raise")\n        req = {"street": self.street, "pot": sum(self.committed),\n               "my_bet": self.bets[a], "opp_bet": self.bets[o], "to_call": to_call,\n               "my_stack": self.stacks[a], "opp_stack": self.stacks[o], "legal_actions": legal}\n        if can_raise:\n            req["min_raise"] = min(self.bets[o] + max(self.last_raise, 2), max_raise)\n            req["max_raise"] = max_raise\n        req["raises_left"] = MAX_RAISES - self.raises\n        return req\n\n    def apply(self, action, amount=None):\n        """Apply a legal action; raises ValueError on an illegal one (state unchanged)."""\n        if self.done:\n            raise ValueError("street is over")\n        req = self.request()\n        if action not in req["legal_actions"]:\n            raise ValueError(f"{action} not legal on {self.street}: {req[\'legal_actions\']}")\n        if action == "raise":\n            if isinstance(amount, bool) or not isinstance(amount, int) \\\n                    or not req["min_raise"] <= amount <= req["max_raise"]:\n                raise ValueError(f"raise amount {amount!r} outside [{req[\'min_raise\']}, {req[\'max_raise\']}]")\n        a, o = self.actor, 1 - self.actor\n        if action == "fold":\n            self.folder = a\n            self.done = True\n            self._finish()\n            return\n        if action == "call":\n            to_call = self.bets[o] - self.bets[a]\n            self.stacks[a] -= to_call\n            self.committed[a] += to_call\n            self.bets[a] = self.bets[o]\n        elif action == "raise":\n            add = amount - self.bets[a]\n            self.stacks[a] -= add\n            self.committed[a] += add\n            self.last_raise = amount - self.bets[o]\n            self.bets[a] = amount\n            self.raises += 1\n            self.acted[o] = False\n            if self.hand is not None:\n                if self.street == "preflop":\n                    self.hand.pagg = a + 1\n                elif self.street == "flop":\n                    self.hand.fagg = a + 1\n        self.acted[a] = True\n        if self.acted[0] and self.acted[1] and self.bets[0] == self.bets[1]:\n            self.done = True\n            self._finish()\n            return\n        self.actor = o\n\n    def _finish(self):\n        if self.hand is not None:\n            self.hand.street_bets[self.street] = tuple(self.bets)\n            if self.folder is not None:\n                self.hand.folder = self.folder\n\n\nclass HandState:\n    """Chip state across streets, plus the context features pot-at-street-start, pagg, fagg."""\n\n    def __init__(self):\n        self.stacks = [STARTING_STACK - SMALL_BLIND, STARTING_STACK - BIG_BLIND]\n        self.committed = [SMALL_BLIND, BIG_BLIND]\n        self.pot_start = {}\n        self.street_bets = {}\n        self.pagg = 0          # 0 none, 1 button, 2 big blind (last voluntary preflop raise)\n        self.fagg = 0          # same for flop bets and raises\n        self.folder = None\n        self.cur = None\n\n    def start_street(self, street):\n        self.pot_start[street] = sum(self.committed)\n        self.cur = StreetState(street, self.stacks, self.committed, self)\n        if self.cur.done:\n            self.street_bets[street] = (0, 0)\n        return self.cur\n\n\n# ---------------------------------------------------------------- history replay\n\nStep = namedtuple("Step", "street node seat actor slot action amount req")\n\n\n# Default raise translation for replay_history: a deterministic stand-in used by tools and tests.\n# The bot passes its §9.4 translation (botsrc/translate.py) instead. A translate function is called as\n# translate(node, opts, amount, max_raise, street=..., index=..., seat=..., req=...), where index is\n# the entry\'s position in the history.\ndef nearest_translate(node, opts, amount, max_raise, **_):\n    """Placeholder mapping of a raise to a slot (§9.4 translation arrives in Phase 6):\n    all-in -> allin; anything else -> the size slot with the nearest amount (legal ones first).\n    Never maps a non-all-in raise to allin, so the node keeps tracking the engine exactly."""\n    if amount == max_raise and "allin" in node["slots"]:\n        return "allin"\n    cands = [(s, a) for s, ok, a in opts if ok and s in SIZE_SLOTS]\n    if not cands:\n        cands = [(s, a) for s, ok, a in opts if s in SIZE_SLOTS and a is not None]\n    if not cands:\n        return None\n    return min(cands, key=lambda sa: abs(sa[1] - amount))[0]\n\n\nclass Replay:\n    """Result of replay_history."""\n\n    def __init__(self):\n        self.steps = []\n        self.committed = None\n        self.stacks = None\n        self.pot_start = {}\n        self.street_bets = {}\n        self.pagg = 0\n        self.fagg = 0\n        self.folder = None\n        self.current_street = None\n        self.current_node = None\n        self.current_state = None\n        self.lost = False          # an action could not be mapped to a slot\n        self.error = None          # the history is inconsistent with the rules\n\n\nclass StreetReplay:\n    """Walks one street\'s protocol history entries; yields Step(node, slot, amount, actor, ...)."""\n\n    def __init__(self, hand, street, my_seat, translate):\n        self.hand = hand\n        self.street = street\n        self.my_seat = my_seat\n        self.translate = translate\n        self.state = hand.start_street(street)\n        self.tmpl = template_for(street)\n        self.node = 0\n        self.lost = False\n\n    def step(self, entry, index=None):\n        if not isinstance(entry, dict):\n            raise ValueError(f"history entry is not an object: {entry!r}")\n        if entry.get("street") != self.street:\n            raise ValueError(f"{entry.get(\'street\')!r} action while {self.street} betting is open")\n        who = entry.get("actor")\n        if who not in ("me", "opp"):\n            raise ValueError(f"bad actor {who!r}")\n        seat = self.my_seat if who == "me" else 1 - self.my_seat\n        st = self.state\n        if seat != st.actor:\n            raise ValueError(f"seat {seat} acted, expected seat {st.actor}")\n        req = st.request()\n        action = entry.get("action")\n        amount = entry.get("amount") if action == "raise" else None\n        if action == "call" and entry.get("amount") is not None and entry["amount"] != req["opp_bet"]:\n            raise ValueError(f"call to {entry[\'amount\']}, expected {req[\'opp_bet\']}")\n        node, slot = self.node, None\n        if node is not None and node >= 0:\n            nd = self.tmpl[node]\n            if action in ("fold", "check", "call"):\n                slot = action if action in nd["slots"] else None\n            elif action == "raise" and "raise" in req["legal_actions"] and isinstance(amount, int):\n                slot = self.translate(nd, slot_options_req(self.street, nd, req), amount, req["max_raise"],\n                                      street=self.street, index=index, seat=seat, req=req)\n        st.apply(action, amount)                     # ValueError if illegal\n        actor = None\n        if node is not None and node >= 0:\n            actor = self.tmpl[node]["actor"]\n        if slot is None:\n            self.lost = True\n            self.node = None\n        else:\n            self.node = self.tmpl[node]["child"][slot]\n        return Step(self.street, node, seat, actor, slot, action, amount, req)\n\n\ndef replay_history(history, my_seat, translate=None):\n    """Replay a protocol `history` (all streets) from my_seat\'s view (0 button, 1 big blind).\n    Never raises: inconsistencies set .error, unmappable actions set .lost."""\n    translate = translate or nearest_translate\n    rep = Replay()\n    hand = HandState()\n    i, n = 0, len(history)\n    try:\n        for street in STREETS:\n            sr = StreetReplay(hand, street, my_seat, translate)\n            rep.current_street = street\n            while not sr.state.done and i < n:\n                rep.steps.append(sr.step(history[i], i))\n                i += 1\n            rep.current_node = sr.node\n            rep.current_state = sr.state\n            rep.lost = rep.lost or sr.lost\n            if not sr.state.done or sr.state.folder is not None:\n                break\n        if i < n:\n            raise ValueError(f"{n - i} history entries left after the betting ended")\n    except (ValueError, KeyError, TypeError, IndexError) as ex:\n        rep.error = str(ex)\n    rep.committed = list(hand.committed)\n    rep.stacks = list(hand.stacks)\n    rep.pot_start = dict(hand.pot_start)\n    rep.street_bets = dict(hand.street_bets)\n    rep.pagg, rep.fagg, rep.folder = hand.pagg, hand.fagg, hand.folder\n    return rep\n'),
    'shared.infoset': (False, '"""Infoset layout: dense tables, prefix formulas and offsets (BUILDMAP §5.3).\n\nProbability of (table, prefix, node, slot) = T[prefix, node.offset + slot_position].\nConcatenated order (trainer arrays, checkpoints, exported blob): PRE, FLOP, DISC, TURN, RIVER.\n"""\nimport numbers\n\nfrom .betting import POST_SLOTS, PRE_SLOTS\n\nN_PRE = 1755\nN_B3 = 400\nN_BT = 200\nN_BR = 100\nN_PC = 6\nN_AGG = 3\nN_SEAT = 2\nN_DCLS = 4\nN_KEEP = 3\n\nTABLES = ("PRE", "FLOP", "DISC", "TURN", "RIVER")\nPREFIXES = {\n    "PRE": N_PRE,\n    "FLOP": N_B3 * N_PC * N_AGG,\n    "DISC": N_B3 * N_PC * N_AGG * N_SEAT,\n    "TURN": N_BT * N_DCLS * N_DCLS * N_PC,\n    "RIVER": N_BR * N_DCLS * N_PC,\n}\nSLOTS = {"PRE": PRE_SLOTS, "FLOP": POST_SLOTS, "DISC": N_KEEP, "TURN": POST_SLOTS, "RIVER": POST_SLOTS}\nSIZES = {t: PREFIXES[t] * SLOTS[t] for t in TABLES}\nOFFSETS = {}\n_off = 0\nfor _t in TABLES:\n    OFFSETS[_t] = _off\n    _off += SIZES[_t]\nTOTAL = _off\nassert TOTAL == 2_787_570\n\n\ndef _check(name, v, n):\n    if not (isinstance(v, numbers.Integral) and not isinstance(v, bool) and 0 <= v < n):\n        raise ValueError(f"{name}={v!r} outside [0, {n})")\n\n\ndef pre_prefix(hand):\n    _check("hand", hand, N_PRE)\n    return hand\n\n\ndef flop_prefix(b3, pc, pagg):\n    _check("b3", b3, N_B3); _check("pc", pc, N_PC); _check("pagg", pagg, N_AGG)\n    return (b3 * 6 + pc) * 3 + pagg\n\n\ndef disc_prefix(b3, pc, fagg, seat):\n    _check("b3", b3, N_B3); _check("pc", pc, N_PC); _check("fagg", fagg, N_AGG); _check("seat", seat, N_SEAT)\n    return ((b3 * 6 + pc) * 3 + fagg) * 2 + seat\n\n\ndef turn_prefix(bt, od, md, pc):\n    _check("bt", bt, N_BT); _check("od", od, N_DCLS); _check("md", md, N_DCLS); _check("pc", pc, N_PC)\n    return ((bt * 4 + od) * 4 + md) * 6 + pc\n\n\ndef river_prefix(br, od, pc):\n    _check("br", br, N_BR); _check("od", od, N_DCLS); _check("pc", pc, N_PC)\n    return (br * 4 + od) * 6 + pc\n\n\ndef index(table, prefix, node_offset, slot_pos):\n    """Position in the concatenated array of (table, prefix, node.offset + slot_pos).\n    For DISC, node_offset is 0 and slot_pos is the keep slot."""\n    _check("prefix", prefix, PREFIXES[table])\n    _check("column", node_offset + slot_pos, SLOTS[table])\n    return OFFSETS[table] + prefix * SLOTS[table] + node_offset + slot_pos\n\n\ndef row_range(table, prefix):\n    """[start, stop) of one prefix\'s row in the concatenated array."""\n    start = index(table, prefix, 0, 0)\n    return start, start + SLOTS[table]\n'),
    'shared.blob': (False, '"""The strategy blob embedded in dist/bot.py (BUILDMAP §7 Phase 6, §9.1).\n\nLayout of the raw (decompressed) blob:\n    MAGIC (16 bytes) | header length (u32 little-endian) | header (UTF-8 JSON) | payload\nThe header lists every array: name, dtype, shape, offset into the payload, nbytes; plus free-form\n"meta" and the sha256 of the payload. Arrays start on 8-byte boundaries.\nStored form: base64(zlib.compress(raw, 9)). Deterministic: the same arrays and meta give the same bytes.\nStandard library + numpy only (it runs inside the bot).\n"""\nimport base64\nimport hashlib\nimport json\nimport struct\nimport zlib\n\nimport numpy as np\n\nMAGIC = b"DHCFR-BLOB-v1\\x00\\x00\\x00"\nassert len(MAGIC) == 16\n\n\ndef encode_raw(arrays, meta):\n    """arrays: {name: np.ndarray} (kept in insertion order). Returns the raw, uncompressed blob."""\n    entries, chunks, offset = [], [], 0\n    for name, a in arrays.items():\n        a = np.ascontiguousarray(a)\n        data = a.tobytes()\n        pad = (-offset) % 8\n        chunks.append(b"\\x00" * pad)\n        offset += pad\n        entries.append({"name": name, "dtype": a.dtype.str, "shape": list(a.shape),\n                        "offset": offset, "nbytes": len(data)})\n        chunks.append(data)\n        offset += len(data)\n    payload = b"".join(chunks)\n    header = {"version": 1, "arrays": entries, "meta": meta,\n              "payload_sha256": hashlib.sha256(payload).hexdigest()}\n    hb = json.dumps(header, sort_keys=True, separators=(",", ":")).encode()\n    return MAGIC + struct.pack("<I", len(hb)) + hb + payload\n\n\ndef encode_blob(arrays, meta):\n    """base64(zlib(raw)) as ASCII bytes."""\n    return base64.b64encode(zlib.compress(encode_raw(arrays, meta), 9))\n\n\ndef decode_raw(raw):\n    """(header, {name: read-only np.ndarray view into raw}). Raises ValueError on any problem."""\n    if raw[:16] != MAGIC:\n        raise ValueError("strategy blob: bad magic")\n    (hlen,) = struct.unpack("<I", raw[16:20])\n    header = json.loads(raw[20:20 + hlen].decode())\n    payload = memoryview(raw)[20 + hlen:]\n    if hashlib.sha256(payload).hexdigest() != header["payload_sha256"]:\n        raise ValueError("strategy blob: payload sha256 mismatch")\n    arrays = {}\n    for e in header["arrays"]:\n        n = e["nbytes"]\n        a = np.frombuffer(payload, dtype=np.dtype(e["dtype"]), count=n // np.dtype(e["dtype"]).itemsize,\n                          offset=e["offset"])\n        arrays[e["name"]] = a.reshape(e["shape"])\n    return header, arrays\n\n\ndef decode_blob(b64):\n    """Inverse of encode_blob. b64: ASCII bytes or str (newlines are ignored)."""\n    try:\n        raw = zlib.decompress(base64.b64decode(b64))\n    except (ValueError, zlib.error) as e:\n        raise ValueError(f"strategy blob: cannot decode ({e})") from None\n    return decode_raw(raw)\n'),
    'botsrc': (True, '"""Bot runtime (BUILDMAP §9). Bundled with shared/ into the single file dist/bot.py by tools/build_bot.py."""\n'),
    'botsrc.log': (False, '"""stderr logging with a per-match cap (BUILDMAP §9.11). The engine keeps only 64 KB of stderr."""\nimport sys\n\nLIMIT_BYTES = 20_000\n\n\nclass Log:\n    def __init__(self, limit=LIMIT_BYTES):\n        self.limit = limit\n        self.used = 0\n        self.dropped = 0\n\n    def __call__(self, text):\n        line = text if text.endswith("\\n") else text + "\\n"\n        n = len(line.encode("utf-8", "replace"))\n        if self.used + n > self.limit:\n            self.dropped += 1\n            return\n        self.used += n\n        try:\n            sys.__stderr__.write(line)\n            sys.__stderr__.flush()\n        except Exception:\n            pass\n\n\nlog = Log()\n'),
    'botsrc.protocol': (False, '"""Protocol helpers (Protocol Specification §5-§9, BUILDMAP §9.2): safe replies and legality checks.\n\nEverything here works on untrusted input and never raises.\n"""\nfrom shared.cards import RANKS, SUITS\n\n\ndef _num(x, default):\n    try:\n        return float(x)\n    except Exception:\n        return default\n\n\ndef fallback_action(req):\n    """§9.2: check if legal; else call if to_call <= pot/4; else fold."""\n    legal = req.get("legal_actions") if isinstance(req, dict) else None\n    legal = legal if isinstance(legal, list) else []\n    if "check" in legal:\n        return {"type": "action", "action": "check"}\n    to_call = _num(req.get("to_call"), 1.0) if isinstance(req, dict) else 1.0\n    pot = _num(req.get("pot"), 0.0) if isinstance(req, dict) else 0.0\n    if "call" in legal and to_call <= pot / 4:\n        return {"type": "action", "action": "call"}\n    if "fold" in legal:\n        return {"type": "action", "action": "fold"}\n    if "call" in legal:\n        return {"type": "action", "action": "call"}\n    return {"type": "action", "action": "check"}\n\n\ndef default_discard(hole):\n    """The engine\'s own default (lowest rank; spades, hearts, diamonds, clubs first), sent explicitly\n    so the engine does not need to correct us. None if no hole card is valid."""\n    if not isinstance(hole, list):\n        return None\n    valid = [c for c in hole if isinstance(c, str) and len(c) == 2 and c[0] in RANKS and c[1] in SUITS]\n    if not valid:\n        return None\n    return min(valid, key=lambda c: (RANKS.index(c[0]), SUITS.index(c[1])))\n\n\ndef legal_reply(reply, req):\n    """True iff the engine would accept this action reply for this request (engine.parse_action)."""\n    try:\n        if not isinstance(reply, dict) or reply.get("type") != "action":\n            return False\n        a = reply.get("action")\n        if a not in req["legal_actions"]:\n            return False\n        if a == "raise":\n            amt = reply.get("amount")\n            return type(amt) is int and req["min_raise"] <= amt <= req["max_raise"]\n        return True\n    except Exception:\n        return False\n'),
    'botsrc.translate': (False, '"""Action translation for bet sizes outside our tree (BUILDMAP §9.4).\n\nraise to X: X == max_raise -> allin. Otherwise the candidates are the legal size slots and allin at\nthe node, with their §5.2.3 amounts, compared as pot fractions:\n    opening bet (opp_bet == 0):  f = X / pot\n    raise:                       f = (X - opp_bet) / (pot + to_call)\nBelow the smallest -> smallest; above the largest -> largest. Between neighbours A < x < B:\n    P(A) = ((B - x)(1 + A)) / ((B - A)(1 + x))        (pseudo-harmonic mapping)\nsampled with random.Random(hash(key)), key = (hand_id, street index, history index), so the same\naction always maps to the same slot within a hand. Range tracking uses the mixture, not the sample.\n"""\nimport random\n\nfrom shared import betting as B\n\nCANDIDATE_SLOTS = ("sizeA", "sizeB", "raise", "allin")\n\n\ndef fraction(amount, req):\n    pot, opp_bet, to_call = req["pot"], req["opp_bet"], req["to_call"]\n    if opp_bet == 0:\n        return amount / max(pot, 1)\n    return (amount - opp_bet) / max(pot + to_call, 1)\n\n\ndef translate_raise(node, opts, amount, req, key):\n    """-> (slot, [(slot, probability), ...]) for a raise to `amount` at `node`."""\n    if amount == req.get("max_raise") and "allin" in node["slots"]:\n        return "allin", [("allin", 1.0)]\n    cands = [(s, a) for s, ok, a in opts if ok and s in CANDIDATE_SLOTS and a is not None]\n    if not cands:   # no legal size: any size slot of the node, else allin (keeps the walk on the tree)\n        cands = [(s, a) for s, ok, a in opts if s in CANDIDATE_SLOTS and a is not None]\n    if not cands:\n        return None, []\n    pts = sorted((fraction(a, req), s) for s, a in cands)\n    x = fraction(amount, req)\n    if x <= pts[0][0]:\n        return pts[0][1], [(pts[0][1], 1.0)]\n    if x >= pts[-1][0]:\n        return pts[-1][1], [(pts[-1][1], 1.0)]\n    for (fa, sa), (fb, sb) in zip(pts, pts[1:]):\n        if x == fb:\n            return sb, [(sb, 1.0)]\n        if fa < x < fb:\n            p_a = ((fb - x) * (1 + fa)) / ((fb - fa) * (1 + x))\n            slot = sa if random.Random(hash(key)).random() < p_a else sb\n            return slot, [(sa, p_a), (sb, 1.0 - p_a)]\n    return pts[-1][1], [(pts[-1][1], 1.0)]\n\n\nSTREET_INDEX = {s: i for i, s in enumerate(B.STREETS)}\n'),
    'botsrc.hooks': (False, '"""Hooks for the exploit layer (BUILDMAP §9.9). Every function has a safe default, so the bot works\nwith no exploit layer. The teammate\'s layer replaces these functions (same names and signatures).\n\nRules for the layer (the bot enforces the cap and the time budget as a safety net):\n  - strength n / (n + 50) for an adjustment backed by n observations\n  - act only on deviations from the blueprint baseline larger than 2 standard errors\n  - shift each decision by at most 0.3 total variation from the incoming distribution\n  - at most 5 ms per decision (exploit_adjust plus its share of on_event)\n"""\n\nDEFAULT_TAU = 0.7\n\n\ndef on_event(msg):\n    """Called with every engine message (dict), for opponent modelling."""\n    return None\n\n\ndef exploit_adjust(ctx, dist):\n    """dist: {label: probability} over the legal options (ctx.options). Return a new distribution."""\n    return dist\n\n\ndef opp_model():\n    """A small dict summarising the opponent for the river solver (ctx.opp_model), or None."""\n    return None\n\n\ndef range_tau():\n    """Opponent-range tempering exponent (§9.6), in (0, 1]. Our own range is never tempered."""\n    return DEFAULT_TAU\n\n\ndef opp_action_likelihood(action):\n    """Optional §9.6 range factor: float64[1326] over the opponent\'s candidate pairs, or None."""\n    return None\n'),
    'botsrc.timeman': (False, '"""Time manager (BUILDMAP §9.8), calibrated from measured costs.\n\nPer remaining hand the bot has B = (time_left_ms - HARD_RESERVE x starting bank) / hands_left\n(hands_left = total_hands - hand_id + 1): 10% of the bank is never planned against, so a slow\nmachine cannot run the bank down to nothing at the end of a match. It compares B with what each\nmode costs, measured on this machine:\n    lean  = our own cost per hand without range tracking (features, lookups, replay)\n    full  = lean + range tracking per river hand x the share of hands that reach a river decision\n    NORMAL  if B >= full + river_rate x RIVER_MIN_MS + reserve   (ranges + river solver)\n    LEAN    if B >= lean + reserve                               (blueprint only)\n    PANIC   otherwise                                            (no feature passes)\nCosts start from M4 priors scaled by speed_factor (start-up calibration: one turn street_rows pass\n/ REF_MS) and move to the measured values as hands are played (weight n / (n + 30)). The reserve is\nthe larger of the prior and the measured overhead per hand: the engine-charged time (how\ntime_left_ms falls between our requests) minus what our own timers saw, which covers pipes, JSON\nand scheduling delays on a busy or throttled machine.\n\nRiver solver budget in NORMAL. Plan to use at most TARGET_USE (70%, BUILDMAP §11) of the bank:\n    B_plan = (time_left - (1 - TARGET_USE) x starting bank) / hands_left\n    afford_plan = (B_plan - full - reserve) / river_rate      per river decision, within the plan\n    afford_real = (B      - full - reserve) / river_rate      per river decision, the real bank\nbudget = min(max(RIVER_MIN_MS, afford_plan), afford_real), at most RIVER_MAX_MS, 40% of the\nper-reply limit and 2% of the bank left; 0 (do not call the solver) if afford_real or the caps are\nunder RIVER_MIN_MS. A solver that always uses its whole budget then ends a match near 70% of the\nbank. On a slow machine where the plan cannot hold, NORMAL still gives RIVER_MIN_MS (the real bank\naffords it, by NORMAL\'s threshold); if costs then run over, B dips under NORMAL\'s threshold, a few\nhands play LEAN, and the bank recovers.\n"""\nimport time\n\nNORMAL, LEAN, PANIC = "NORMAL", "LEAN", "PANIC"\n\n# M4 (Apple, numpy 1.26) measurements, 3 Nov 2026 23:44, run B paused, Stage 2 matches (BUILDMAP §9.1,\n# §9.8). Priors are the most expensive opponent measured (check/call: a river on nearly every hand);\n# against the random bot: own 10.1 ms/hand, 0.44 river hands/hand, 0.51 river decisions/hand.\nREF_MS = 9.6             # one turn street_rows pass (start-up calibration), same thermal state as below\nLEAN_M4 = 16.0           # own ms per hand without range tracking (check/call: 15.6; random: 10.1)\nRANGE_M4 = 12.0          # range tracking ms per river hand\nRIVER_HAND_RATE = 0.6    # share of hands with a river decision (prior; random 0.44, check/call 0.98)\nRIVER_DECISION_RATE = 0.7  # river decisions per hand (prior; random 0.51, check/call 0.98)\n\nRIVER_MIN_MS = 50.0      # the solver must be usable at this budget (§10, anytime)\nRIVER_MAX_MS = 1500.0\nTARGET_USE = 0.7         # plan to use at most this share of the time bank (BUILDMAP §11: Stage 2 <= 70%)\nHARD_RESERVE = 0.10      # never plan against this share of the starting bank (modes and budgets)\nRESERVE_M4 = 3.0         # prior per-hand overhead not seen by the decision timers (scaled by speed);\n                         # replaced by the measured overhead: engine-charged time - our own timers\nPRIOR_HANDS = 30\n\n\ndef now_ms():\n    return time.perf_counter() * 1000.0\n\n\nclass TimeManager:\n    def __init__(self, speed_factor=1.0):\n        self.speed_factor = speed_factor\n        self.total_hands = 400\n        self.per_response_ms = 5000.0\n        self.bank_ms = None\n        self.modes = {NORMAL: 0, LEAN: 0, PANIC: 0}\n        self.street_ms = {}\n        self.street_n = {}\n        # per-hand accounting (current hand) and running totals over finished hands\n        self.cur = None\n        self.hands = 0\n        self.own_ms = 0.0          # all our decision time except range tracking and the solver\n        self.range_ms = 0.0\n        self.range_hands = 0\n        self.river_hands = 0\n        self.river_decisions = 0\n        self.solver_ms = 0.0\n        self.solver_calls = 0\n        self.budget_ms = 0.0\n        self.dec = {"range": 0.0, "solver": 0.0}\n        # engine-charged time vs our own timers (overhead measurement)\n        self.last_time_left = None\n        self.last_reply_ms = None\n        self.charged_ms = 0.0\n        self.timed_ms = 0.0\n        self.replies_obs = 0\n        self.replies = 0\n\n    def set_match(self, total_hands, per_response_ms, time_bank_ms=None):\n        self.total_hands = max(1, int(total_hands))\n        self.per_response_ms = float(per_response_ms)\n        if time_bank_ms:\n            self.bank_ms = float(time_bank_ms)\n\n    # ---------------- accounting\n\n    def begin_hand(self, hand_id):\n        self.end_hand()\n        self.cur = {"own": 0.0, "range": 0.0, "river": 0}\n\n    def end_hand(self):\n        c = self.cur\n        if c is None:\n            return\n        self.hands += 1\n        self.own_ms += c["own"]\n        if c["range"] > 0:\n            self.range_ms += c["range"]\n            self.range_hands += 1\n        if c["river"]:\n            self.river_hands += 1\n            self.river_decisions += c["river"]\n        self.cur = None\n\n    def add(self, own_ms=0.0, range_ms=0.0, solver_ms=0.0, river_decision=False):\n        if self.cur is None:\n            self.cur = {"own": 0.0, "range": 0.0, "river": 0}\n        self.cur["own"] += own_ms\n        self.cur["range"] += range_ms\n        self.cur["river"] += 1 if river_decision else 0\n        self.solver_ms += solver_ms\n\n    def observe(self, req):\n        """Call when a request arrives: the drop in time_left_ms since the previous request is what the\n        engine charged for our previous reply."""\n        try:\n            tl = float(req["time_left_ms"])\n        except Exception:\n            return\n        if self.bank_ms is None:\n            self.bank_ms = tl\n        if self.last_time_left is not None and self.last_reply_ms is not None:\n            charged = self.last_time_left - tl\n            if charged > 0:                     # 0 inside the engine\'s free start-up window\n                self.charged_ms += charged\n                self.timed_ms += self.last_reply_ms\n                self.replies_obs += 1\n        self.last_time_left = tl\n        self.last_reply_ms = None\n\n    def replied(self, ms):\n        self.last_reply_ms = ms\n        self.replies += 1\n\n    def begin_decision(self):\n        self.dec = {"range": 0.0, "solver": 0.0}\n\n    def note_range(self, ms):\n        self.dec["range"] += ms\n\n    def note_solver(self, ms, budget):\n        self.dec["solver"] += ms\n        self.solver_calls += 1\n        self.budget_ms += budget\n\n    def record(self, street, ms):\n        self.street_ms[street] = self.street_ms.get(street, 0.0) + ms\n        self.street_n[street] = self.street_n.get(street, 0) + 1\n\n    # ---------------- estimates (ms per hand on this machine)\n\n    def _blend(self, measured, n, prior):\n        w = n / (n + PRIOR_HANDS)\n        return w * measured + (1 - w) * prior\n\n    def costs(self):\n        sf = self.speed_factor\n        n = self.hands\n        lean = self._blend(self.own_ms / n if n else 0.0, n, LEAN_M4 * sf)\n        rng = self._blend(self.range_ms / self.range_hands if self.range_hands else 0.0, self.range_hands,\n                          RANGE_M4 * sf)\n        hand_rate = self._blend(self.river_hands / n if n else 0.0, n, RIVER_HAND_RATE)\n        dec_rate = self._blend(self.river_decisions / n if n else 0.0, n, RIVER_DECISION_RATE)\n        reserve = RESERVE_M4 * sf\n        if self.replies_obs >= 20 and n:\n            per_reply = max(0.0, (self.charged_ms - self.timed_ms) / self.replies_obs)\n            reserve = max(reserve, per_reply * self.replies / n)\n        return {"lean": lean, "full": lean + rng * hand_rate, "range": rng, "river_rate": max(dec_rate, 0.05),\n                "reserve": reserve}\n\n    def per_hand(self, req, hand_id, total_hands):\n        """B: ms per remaining hand, after setting aside the hard reserve."""\n        hands_left = max(1, int(total_hands) - int(hand_id) + 1)\n        time_left = float(req["time_left_ms"])\n        if self.bank_ms is None:\n            self.bank_ms = time_left\n        return (time_left - HARD_RESERVE * self.bank_ms) / hands_left\n\n    def mode(self, req, hand_id, total_hands=None):\n        try:\n            B = self.per_hand(req, hand_id, total_hands or self.total_hands)\n        except Exception:\n            m = NORMAL\n        else:\n            c = self.costs()\n            if B >= c["full"] + c["river_rate"] * RIVER_MIN_MS + c["reserve"]:\n                m = NORMAL\n            elif B >= c["lean"] + c["reserve"]:\n                m = LEAN\n            else:\n                m = PANIC\n        self.modes[m] += 1\n        return m\n\n    def river_budget_ms(self, req, hand_id, total_hands=None):\n        try:\n            total = total_hands or self.total_hands\n            hands_left = max(1, int(total) - int(hand_id) + 1)\n            time_left = float(req["time_left_ms"])\n            B = self.per_hand(req, hand_id, total)\n        except Exception:\n            return 0.0\n        c = self.costs()\n        B_plan = (time_left - (1.0 - TARGET_USE) * self.bank_ms) / hands_left\n        afford_real = (B - c["full"] - c["reserve"]) / c["river_rate"]\n        if afford_real < RIVER_MIN_MS:\n            return 0.0\n        afford_plan = (B_plan - c["full"] - c["reserve"]) / c["river_rate"]\n        budget = min(max(RIVER_MIN_MS, afford_plan), afford_real)\n        budget = min(budget, RIVER_MAX_MS, 0.4 * self.per_response_ms, 0.02 * time_left)\n        return budget if budget >= RIVER_MIN_MS else 0.0\n\n    def summary(self):\n        self.end_hand()\n        n = max(1, self.hands)\n        c = self.costs()\n        over = (self.charged_ms - self.timed_ms) / self.replies_obs if self.replies_obs else 0.0\n        return (f"overhead {over:.2f} ms per reply (engine-charged minus own timers, {self.replies_obs} replies); "\n                f"own time per hand {self.own_ms / n:.1f} ms + ranges {self.range_ms / max(1, self.range_hands):.1f} ms "\n                f"per river hand ({self.range_hands} hands), river decisions/hand {self.river_decisions / n:.2f}, "\n                f"solver {self.solver_calls} calls {self.solver_ms:.0f} ms (budget {self.budget_ms:.0f} ms); "\n                f"estimates lean {c[\'lean\']:.1f} full {c[\'full\']:.1f} ms/hand; modes {self.modes}")\n'),
    'botsrc.state': (False, '"""Per-hand state and history replay (BUILDMAP §9.3).\n\nThe abstract state is rebuilt from the request\'s `history` on every request (stateless and robust).\nThe per-hand cache keeps what the replay cannot know: the slot we chose for each of our own actions\n(keyed by its index in the history), the discards, and street features computed once per street.\n"""\nfrom shared import betting as B\nfrom shared import cards as C\n\nfrom . import translate as TR\n\n\nclass HandState:\n    def __init__(self, msg, mirror=False):\n        self.hand_id = int(msg["hand_id"])\n        self.deal = (self.hand_id - 1) // 2   # hands 2k+1 and 2k+2 share deal k (the engine\'s duplicate pairs)\n        self.mirror = bool(mirror)            # eval builds: random draws keyed by the deal, not the hand\n        seat = msg["seat"]\n        if seat not in ("button", "big_blind"):\n            raise ValueError(f"bad seat {seat!r}")\n        self.seat = 0 if seat == "button" else 1\n        self.hole3 = sorted(C.parse_cards(msg["hole_cards"]))\n        if len(self.hole3) != 3 or len(set(self.hole3)) != 3:\n            raise ValueError("need 3 distinct hole cards")\n        self.hole = list(self.hole3)          # 2 cards after the discard\n        self.my_discard = None\n        self.opp_discard = None\n        self.keep_slot = None\n        self.my_actions = {}                  # history index -> {street, node, slot, action, amount}\n        self.history_after = []               # last history we saw + our reply (for the discard key)\n        self.cache = {}                       # street features\n        self.translator = make_translator(self)\n\n    def on_discard_result(self, msg):\n        self.my_discard = C.parse_card(msg["my_discard"])\n        self.opp_discard = C.parse_card(msg["opp_discard"])\n        hole = sorted(C.parse_cards(msg["hole_cards"]))\n        if len(hole) == 2:\n            self.hole = hole\n\n    def on_notice(self, msg):\n        # The engine corrected our last action (pitfall §13.4): forget its cached slot, so the replay\n        # translates what the engine actually applied.\n        if msg.get("code") in ("illegal_action", "malformed") and self.my_actions:\n            self.my_actions.pop(max(self.my_actions))\n\n    def record_own(self, req, reply, node_id, slot):\n        idx = len(req["history"])\n        entry = {"street": req["street"], "actor": "me", "action": reply["action"]}\n        if reply["action"] == "raise":\n            entry["amount"] = reply["amount"]\n        elif reply["action"] == "call":\n            entry["amount"] = req["opp_bet"]\n        self.my_actions[idx] = {"street": req["street"], "node": node_id, "slot": slot,\n                                "action": reply["action"], "amount": reply.get("amount")}\n        self.history_after = list(req["history"]) + [entry]\n\n\ndef make_translator(hs):\n    def translate(node, opts, amount, max_raise, street=None, index=None, seat=None, req=None, **_):\n        if seat == hs.seat:\n            mine = hs.my_actions.get(index)\n            if mine and mine["action"] == "raise" and mine["amount"] == amount and mine["street"] == street \\\n                    and mine["node"] == node["id"] and mine["slot"] in node["slots"]:\n                return mine["slot"]\n        key_hand = hs.deal if hs.mirror else hs.hand_id\n        slot, _ = TR.translate_raise(node, opts, amount, req, (key_hand, TR.STREET_INDEX.get(street, 9), index))\n        return slot\n    return translate\n\n\ndef replay(hs, history):\n    return B.replay_history(history, hs.seat, translate=hs.translator)\n'),
    'botsrc.ranges': (False, '"""Range tracking at the start of the river (BUILDMAP §9.6), vectorised over candidate hands.\n\nOpponent range (our belief): candidates are pairs k from the cards not on the board, not in our 3\nhole cards and not their discard d; their 3-card hand is H = k + {d}. The likelihood of k is the\nproduct, over their preflop / flop / turn actions, of the blueprint probability of what they did\n(off-tree raises: the §9.4 translation mixture), times the probability of their discard (keeping k\nfrom H). Unvisited infosets give a uniform factor over the legal slots; every factor is floored at\n1/1020 and raised to tau (default 0.7, hooks.range_tau()). opp_range = 0.9 tracked + 0.1 flat.\n\nOur range (the opponent\'s view of us): the same with our actions and our discard, candidates\nexcluding only the board and both discards, tau = 1 and no flat mix (we know how we play).\n"""\nimport math\nimport numbers\n\nimport numpy as np\n\nfrom shared import betting as B\nfrom shared import cards as C\nfrom shared import features as F\nfrom shared import showdown as SD\n\nfrom . import hooks\nfrom . import translate as TR\n\nFLOOR = 1.0 / 1020\nFLAT_MIX = 0.1\nDEFAULT_TAU = 0.7\n_C3 = np.array([math.comb(n, 3) for n in range(52)], dtype=np.int64)\n_C2 = np.array([math.comb(n, 2) for n in range(52)], dtype=np.int64)\n\n\ndef idx3_rows(H):\n    """Vectorised idx3 for rows of sorted triples (n, 3)."""\n    return _C3[H[:, 2]] + _C2[H[:, 1]] + H[:, 0]\n\n\ndef valid_tau(x):\n    try:\n        x = float(x)\n    except Exception:\n        return DEFAULT_TAU\n    return x if 0.0 < x <= 1.0 and math.isfinite(x) else DEFAULT_TAU\n\n\ndef all_pairs(policy, hs, street, board):\n    """S1, S2 for all 1326 pairs on the flop or the turn (lookahead), cached per hand."""\n    key = ("all", street, tuple(board[:3 if street == "flop" else 4]))\n    if key not in hs.cache:\n        if street == "flop":\n            rows = policy.flop_info(hs, board)["rows"]\n        else:\n            rows = policy.later_info(hs, "turn", board)["rows"]     # cached by our own turn decision\n        hs.cache[key] = F.all_features(rows)\n    return hs.cache[key]\n\n\ndef river_buckets(policy, hs, board):\n    key = ("br_all", tuple(board[:5]))\n    if key not in hs.cache:\n        E, _ = F.all_features(F.street_rows(board[:5], False))\n        hs.cache[key] = F.river_bucket_all(E, policy.th)\n    return hs.cache[key]\n\n\ndef action_records(rep, hs, seat, streets=("preflop", "flop", "turn")):\n    """The actions of `seat` on these streets: node, legal mask, and slot weights (one slot for exact\n    actions, the §9.4 mixture for off-tree raises)."""\n    out = []\n    for index, st in enumerate(rep.steps):\n        if st.seat != seat or st.street not in streets or st.node is None or st.node < 0:\n            continue\n        node = B.template_for(st.street)[st.node]\n        opts = B.slot_options_req(st.street, node, st.req)\n        legal = np.array([1.0 if ok else 0.0 for _, ok, _ in opts])\n        if st.action == "raise":\n            if seat == hs.seat and st.slot is not None:\n                mix = {st.slot: 1.0}                       # our own raise: exactly the slot we played\n            else:\n                _, pairs = TR.translate_raise(node, opts, st.amount, st.req,\n                                              (hs.hand_id, TR.STREET_INDEX[st.street], index))\n                mix = dict(pairs)\n        else:\n            mix = {st.action: 1.0}\n        w = np.array([mix.get(s, 0.0) for s in node["slots"]])\n        out.append({"street": st.street, "node": node, "legal": legal, "w": w, "action": st.action,\n                    "amount": st.amount, "req": st.req, "index": index})\n    return out\n\n\ndef table_factor(rows_u8, legal, w):\n    """Per candidate: sum over slots of w * (strategy row masked to the legal slots, normalised);\n    a row with no legal mass (unvisited) counts as uniform over the legal slots."""\n    p = rows_u8.astype(np.float64) * legal\n    s = p.sum(axis=1, keepdims=True)\n    uniform = legal / legal.sum()\n    sigma = np.where(s > 0, p / np.where(s > 0, s, 1.0), uniform)\n    return sigma @ w\n\n\ndef _custom_factor(action_rec, K):\n    """hooks.opp_action_likelihood: a float64[1326] over candidate pairs, or None (blueprint)."""\n    try:\n        arr = hooks.opp_action_likelihood({k: action_rec[k] for k in ("street", "action", "amount", "index")}\n                                          | {"node_id": action_rec["node"]["id"],\n                                             "slot_weights": dict(zip(action_rec["node"]["slots"],\n                                                                      action_rec["w"].tolist()))})\n    except Exception:\n        return None\n    if arr is None:\n        return None\n    try:\n        arr = np.asarray(arr, dtype=np.float64)\n    except Exception:\n        return None\n    if arr.shape != (1326,) or not np.isfinite(arr).all() or (arr < 0).any():\n        return None\n    return arr[K]\n\n\ndef log_likelihood(policy, hs, rep, board, whose, tau=None, include_river=False):\n    """(K, logL): candidate pair indices (idx2) and log-likelihoods, before normalisation."""\n    opp = whose == "opp"\n    seat_w = 1 - hs.seat if opp else hs.seat\n    d = hs.opp_discard if opp else hs.my_discard\n    other = hs.my_discard if opp else hs.opp_discard\n    excluded = list(board[:5]) + [d, other] + (list(hs.hole3) if opp else [])\n    K = np.nonzero(~np.isin(C.COMBO, excluded).any(axis=1))[0]\n    pairs = C.COMBO[K]\n    H = np.sort(np.column_stack([pairs, np.full(len(K), d, dtype=np.int64)]), axis=1)\n    if tau is None:\n        tau = valid_tau(hooks.range_tau()) if opp else 1.0\n    th, T = policy.th, policy.tables\n    S1f, S2f = all_pairs(policy, hs, "flop", board)\n    b3, slots = F.bucket3_all(H, S1f, F.class2_all(S1f, S2f, th), th)\n    S1t, S2t = all_pairs(policy, hs, "turn", board)\n    bt = F.turn_bucket_all(S1t, S2t, th)[K]\n    flop = board[:3]\n    od_w, md_w = F.dcls(other, flop), F.dcls(d, flop)      # from seat_w\'s point of view\n    pc_flop = B.pot_class(rep.pot_start["flop"])\n    pc_turn = B.pot_class(rep.pot_start["turn"])\n    logL = np.zeros(len(K))\n\n    def add(f):\n        nonlocal logL\n        logL = logL + tau * np.log(np.maximum(f, FLOOR))\n\n    streets = ("preflop", "flop", "turn", "river") if include_river else ("preflop", "flop", "turn")\n    br = river_buckets(policy, hs, board)[K] if include_river else None\n    for rec in action_records(rep, hs, seat_w, streets):\n        if opp:\n            custom = _custom_factor(rec, K)\n            if custom is not None:\n                add(custom)\n                continue\n        node = rec["node"]\n        off, k = node["offset"], len(node["slots"])\n        st = rec["street"]\n        if st == "preflop":\n            rows = T["PRE"][policy.canon3[idx3_rows(H)].astype(np.int64), off:off + k]\n        elif st == "flop":\n            rows = T["FLOP"][(b3 * 6 + pc_flop) * 3 + rep.pagg, off:off + k]\n        elif st == "turn":\n            rows = T["TURN"][((bt * 4 + od_w) * 4 + md_w) * 6 + pc_turn, off:off + k]\n        else:\n            pc_river = B.pot_class(rep.pot_start["river"])\n            rows = T["RIVER"][(br * 4 + od_w) * 6 + pc_river, off:off + k]\n        add(table_factor(rows, rec["legal"], rec["w"]))\n    # the discard: keeping k from H, at the DISC infoset of seat_w\n    keep = np.argmax(slots == K[:, None], axis=1)\n    pc_end = B.pot_class(rep.pot_start["turn"])                 # pot at the end of flop betting\n    rows = T["DISC"][((b3 * 6 + pc_end) * 3 + rep.fagg) * 2 + seat_w, 0:3].astype(np.float64)\n    s = rows.sum(axis=1)\n    sigma = np.where(s[:, None] > 0, rows / np.where(s > 0, s, 1.0)[:, None], 1.0 / 3.0)\n    add(sigma[np.arange(len(K)), keep])\n    return K, logL\n\n\ndef normalise(K, logL, flat_mix):\n    L = np.exp(logL - logL.max())\n    out = np.zeros(1326)\n    out[K] = L / L.sum()\n    if flat_mix > 0:\n        flat = np.zeros(1326)\n        flat[K] = 1.0 / len(K)\n        out = (1.0 - flat_mix) * out + flat_mix * flat\n    return out\n\n\nclass RiverRanges:\n    def __init__(self, opp, our, tau):\n        self.opp = opp\n        self.our = our\n        self.tau = tau\n\n\ndef river_ranges(policy, hs, rep, board):\n    """Both ranges at the start of the river (cache them per hand)."""\n    tau = valid_tau(hooks.range_tau())\n    Ko, lo = log_likelihood(policy, hs, rep, board, "opp", tau=tau)\n    Ku, lu = log_likelihood(policy, hs, rep, board, "our", tau=1.0)\n    return RiverRanges(normalise(Ko, lo, FLAT_MIX), normalise(Ku, lu, 0.0), tau)\n\n\ndef opp_range_now(policy, hs, rep, board, tau):\n    """The opponent range including their river actions so far (blueprint RIVER table)."""\n    K, logL = log_likelihood(policy, hs, rep, board, "opp", tau=tau, include_river=True)\n    return normalise(K, logL, FLAT_MIX)\n\n\ndef equity(board, hole, opp_weights):\n    """Our showdown equity on a 5-card board against a weighted opponent range (ties count half)."""\n    values = SD.river_values(board)\n    beat, tie = SD.weighted_showdown(values, opp_weights, board)\n    h = C.idx2(*hole)\n    ok = ~np.isin(C.COMBO, list(hole)).any(axis=1)\n    total = float(np.asarray(opp_weights)[ok].sum())\n    return float((beat[h] + 0.5 * tie[h]) / total) if total > 0 else 0.0\n\n\ndef is_number(x):\n    return isinstance(x, numbers.Real) and not isinstance(x, bool) and math.isfinite(float(x))\n'),
    'botsrc.policy': (False, '"""Blueprint decisions (BUILDMAP §9.5, §9.10): table lookups with legality masks, the fallback chain,\npurification, the exploit hook (behind a safety net) and sampling."""\nimport math\nimport numbers\nimport random\n\nimport numpy as np\n\nfrom shared import betting as B\nfrom shared import cards as C\nfrom shared import features as F\nfrom shared import infoset as I\n\nfrom . import hooks\nfrom . import ranges as RG\nfrom . import river_api\nfrom .timeman import NORMAL, PANIC, now_ms\n\nPURIFY_EPS = 0.03\nTV_CAP = 0.3\nEXPLOIT_MS = 5.0\nEXPLOIT_KILL_MS = 50.0\nMAX_S1 = {"flop": 47 * 2 * 1035, "turn": 46 * 2 * 990, "river": 2 * 990}\nDISC_NODE = {"id": 0, "offset": 0, "slots": ["keep0", "keep1", "keep2"], "kind": "DISC"}\nSAMPLE_STREET = {"preflop": 0, "flop": 1, "turn": 2, "river": 3, "discard": 4}\n\n\nclass DecisionContext:\n    """What hooks.exploit_adjust sees (§9.9)."""\n\n    def __init__(self, **kw):\n        self.street = kw.get("street")\n        self.request = kw.get("request")\n        self.node_id = kw.get("node_id")\n        self.options = kw.get("options", {})\n        self.slot_amounts = kw.get("slot_amounts", {})\n        self.bucket = kw.get("bucket")\n        self.prefix_key = kw.get("prefix_key")\n        self.pc = kw.get("pc")\n        self.pagg = kw.get("pagg")\n        self.fagg = kw.get("fagg")\n        self.my_discard = kw.get("my_discard")\n        self.opp_discard = kw.get("opp_discard")\n        self.opp_range = kw.get("opp_range")\n        self.our_range = kw.get("our_range")\n        self.mode = kw.get("mode")\n        self.source = kw.get("source", "blueprint")\n\n\ndef purify(dist, eps=PURIFY_EPS):\n    """Zero probabilities below eps, renormalise (§9.5). Keeps the largest entry if all are below."""\n    kept = {k: (v if v >= eps else 0.0) for k, v in dist.items()}\n    s = sum(kept.values())\n    if s <= 0:\n        best = max(dist, key=dist.get)\n        return {k: (1.0 if k == best else 0.0) for k in dist}\n    return {k: v / s for k, v in kept.items()}\n\n\nclass ExploitGuard:\n    """Safety net around hooks.exploit_adjust (§9.9): legal labels only, renormalised, total-variation\n    cap 0.3, exceptions -> identity, time budget (disabled after a call > 50 ms or a mean > 5 ms)."""\n\n    def __init__(self):\n        self.calls = 0\n        self.total_ms = 0.0\n        self.over = 0\n        self.errors = 0\n        self.capped = 0\n        self.disabled = False\n\n    def charge(self, ms):\n        self.total_ms += ms\n        if ms > EXPLOIT_KILL_MS:\n            self.disabled = True\n\n    def apply(self, fn, ctx, base):\n        if self.disabled:\n            return base\n        t0 = now_ms()\n        try:\n            out = fn(ctx, dict(base))\n        except Exception:\n            self.errors += 1\n            out = None\n        dt = now_ms() - t0\n        self.calls += 1\n        self.charge(dt)\n        if dt > EXPLOIT_MS:\n            self.over += 1\n        if self.calls >= 20 and self.total_ms / self.calls > EXPLOIT_MS:\n            self.disabled = True\n        if not isinstance(out, dict):\n            return base\n        allowed = set(ctx.options) if ctx is not None and getattr(ctx, "options", None) else set(base)\n        clean = {}\n        for k, v in out.items():\n            if k in allowed and isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v) and v > 0:\n                clean[k] = float(v)\n        s = sum(clean.values())\n        if s <= 0:\n            return base\n        labels = list(dict.fromkeys(list(base) + list(clean)))\n        new = {k: clean.get(k, 0.0) / s for k in labels}\n        old = {k: base.get(k, 0.0) for k in labels}\n        tv = 0.5 * sum(abs(new[k] - old[k]) for k in labels)\n        if tv > TV_CAP:\n            f = TV_CAP / tv\n            new = {k: old[k] + f * (new[k] - old[k]) for k in labels}\n            self.capped += 1\n        return new\n\n\nclass Policy:\n    def __init__(self, tables, th, canon3, config=None):\n        self.tables = tables\n        self.th = th\n        self.canon3 = canon3\n        self.config = dict(config or {})\n        self.rng = random.Random()\n        # Eval builds only (tools/build_bot.py --sample-seed): every decision draws its random number\n        # from (seed, deal, seat, street, history index), so the two hands of a duplicate pair play\n        # the same spot the same way. Tournament builds use the process RNG.\n        self.mirror = self.config.get("sample_seed") is not None\n\n    # ---------------- fallback candidates (§9.10): (level, prefix), nearest first\n\n    def flop_candidates(self, b3, pc, pagg):\n        c = [("table", I.flop_prefix(b3, pc, pagg))]\n        c += [("pc", I.flop_prefix(b3, p, pagg)) for p in (pc - 1, pc + 1) if 0 <= p < 6]\n        g = b3 % 5\n        c += [("bucket", I.flop_prefix(b3 + d, pc, pagg)) for d in (-1, 1) if 0 <= g + d < 5]\n        return c\n\n    def disc_candidates(self, b3, pc, fagg, seat):\n        c = [("table", I.disc_prefix(b3, pc, fagg, seat))]\n        c += [("pc", I.disc_prefix(b3, p, fagg, seat)) for p in (pc - 1, pc + 1) if 0 <= p < 6]\n        g = b3 % 5\n        c += [("bucket", I.disc_prefix(b3 + d, pc, fagg, seat)) for d in (-1, 1) if 0 <= g + d < 5]\n        return c\n\n    def turn_candidates(self, bt, od, md, pc):\n        c = [("table", I.turn_prefix(bt, od, md, pc))]\n        c += [("pc", I.turn_prefix(bt, od, md, p)) for p in (pc - 1, pc + 1) if 0 <= p < 6]\n        c += [("bucket", I.turn_prefix(bt + d, od, md, pc)) for d in (-5, 5) if 0 <= bt + d < 200]\n        return c\n\n    def river_candidates(self, br, od, pc):\n        c = [("table", I.river_prefix(br, od, pc))]\n        c += [("pc", I.river_prefix(br, od, p)) for p in (pc - 1, pc + 1) if 0 <= p < 6]\n        c += [("bucket", I.river_prefix(br + d, od, pc)) for d in (-1, 1) if 0 <= br + d < 100]\n        return c\n\n    def first_usable(self, table, cands, node, legal_mask):\n        """First candidate row with probability mass on a legal slot -> (probabilities over the\n        node\'s slots, level); (None, None) if none."""\n        off, k = node["offset"], len(node["slots"])\n        mask = np.asarray(legal_mask, dtype=np.float64)\n        for level, prefix in cands:\n            row = self.tables[table][prefix, off:off + k].astype(np.float64) * mask\n            s = row.sum()\n            if s > 0:\n                return row / s, level\n        return None, None\n\n    # ---------------- street features (cached per hand, §9.5)\n\n    def flop_info(self, hs, board):\n        flop = board[:3]\n        key = ("flop", tuple(flop), tuple(hs.hole3))\n        if key not in hs.cache:\n            if len(set(flop) | set(hs.hole3)) != 6:\n                raise ValueError("flop overlaps our hole cards")\n            rows = F.street_rows(flop, True)\n            pairs = F.hand_pairs(hs.hole3)\n            f = F.own_features(rows, pairs)\n            s1 = [x[0] for x in f]\n            b3, slots = F.bucket3(hs.hole3, s1, [x[1] for x in f], self.th)\n            hs.cache[key] = {"rows": rows, "b3": b3, "slots": slots, "s1_best": s1[pairs.index(slots[0])]}\n        return hs.cache[key]\n\n    def later_info(self, hs, street, board):\n        n = 4 if street == "turn" else 5\n        cards = board[:n]\n        key = (street, tuple(cards), tuple(hs.hole))\n        if key not in hs.cache:\n            if len(hs.hole) != 2 or len(set(cards) | set(hs.hole)) != n + 2:\n                raise ValueError(f"{street}: bad kept pair or board")\n            rows = F.street_rows(cards, street == "turn")\n            s1, s2 = F.own_features(rows, [tuple(hs.hole)])[0]\n            if street == "turn":\n                bucket = F.turn_bucket(s1, F.turn_v(s1, s2), self.th)\n            else:\n                bucket = F.river_bucket(s1, self.th)\n            hs.cache[key] = {"rows": rows, "bucket": bucket, "s1": s1}\n        return hs.cache[key]\n\n    # ---------------- decisions\n\n    def decide_action(self, hs, req, rep, mode, guard, stats, tm=None):\n        street = req["street"]\n        board = C.parse_cards(req["board"])\n        node = B.template_for(street)[rep.current_node]\n        opts = B.slot_options_req(street, node, req)\n        legal_mask = [ok for _, ok, _ in opts]\n        if not any(legal_mask):\n            raise ValueError("no legal slot at this node")\n        amounts = {s: a for s, ok, a in opts if ok and a is not None}\n        if mode == PANIC and street != "preflop":\n            stats.level(street, "panic")\n            return self.panic_action(hs, req, street, board), None, node["id"]\n        info = {"street": street, "node": node["id"]}\n        pc = proxy = None\n        if street == "preflop":\n            table = "PRE"\n            cands = [("table", int(self.canon3[C.idx3(*hs.hole3)]))]\n        elif street == "flop":\n            fi = self.flop_info(hs, board)\n            pc = B.pot_class(rep.pot_start["flop"])\n            table, cands, proxy = "FLOP", self.flop_candidates(fi["b3"], pc, rep.pagg), fi["s1_best"] / MAX_S1["flop"]\n            info["bucket"] = fi["b3"]\n        else:\n            li = self.later_info(hs, street, board)\n            flop = board[:3]\n            od, md = F.dcls(hs.opp_discard, flop), F.dcls(hs.my_discard, flop)\n            pc = B.pot_class(rep.pot_start[street])\n            if street == "turn":\n                table, cands = "TURN", self.turn_candidates(li["bucket"], od, md, pc)\n            else:\n                table, cands = "RIVER", self.river_candidates(li["bucket"], od, pc)\n            proxy = li["s1"] / MAX_S1[street]\n            info["bucket"] = li["bucket"]\n        row, level = self.first_usable(table, cands, node, legal_mask)\n        if row is None:\n            label = self.heuristic(node, req, opts, proxy)\n            raw = {label: 1.0}\n        else:\n            raw = {s: float(p) for s, p in zip(node["slots"], row) if p > 0}\n        options = {s: self.action_for(s, amounts, req) for s, ok, _ in opts if ok}\n        rr = None\n        if street == "river" and mode == NORMAL and tm is not None:\n            rr = self.river_ranges(hs, rep, board, tm)\n            out = self.river_special(hs, req, rep, board, node, raw, rr, guard, stats, tm)\n            if out is not None:\n                return out\n        stats.level(street, "heuristic" if row is None else level)\n        dist = purify(raw) if row is not None else raw\n        ctx = DecisionContext(street=street, request=req, node_id=node["id"], options=options, slot_amounts=amounts,\n                              bucket=info.get("bucket"), prefix_key=(table, cands[0][1]), pc=pc, pagg=rep.pagg,\n                              fagg=rep.fagg, my_discard=hs.my_discard, opp_discard=hs.opp_discard, mode=mode,\n                              opp_range=rr.opp if rr else None, our_range=rr.our if rr else None)\n        dist = guard.apply(hooks.exploit_adjust, ctx, dist)\n        label = self.sample(dist, self.sample_key(hs, street, len(req["history"])))\n        return options[label], label, node["id"]\n\n    # ---------------- river (BUILDMAP §9.6, §9.7, §10)\n\n    def river_ranges(self, hs, rep, board, tm):\n        """Both ranges at the start of the river, computed once per hand (NORMAL mode only)."""\n        if "ranges" not in hs.cache:\n            t0 = now_ms()\n            hs.cache["ranges"] = RG.river_ranges(self, hs, rep, board)\n            tm.note_range(now_ms() - t0)\n        return hs.cache["ranges"]\n\n    def river_special(self, hs, req, rep, board, node, blueprint, rr, guard, stats, tm):\n        """The river all-in rule (flag) or the river solver. None: play the blueprint."""\n        legal = req["legal_actions"]\n        rule = self.config.get("river_allin_rule", "off")\n        if rule in ("start", "updated") and req["to_call"] > 0 and req["opp_stack"] == 0 and "call" in legal:\n            if rule == "start":\n                opp = rr.opp\n            else:\n                t0 = now_ms()\n                opp = RG.opp_range_now(self, hs, rep, board, rr.tau)\n                tm.note_range(now_ms() - t0)\n            eq = RG.equity(board[:5], hs.hole, opp)\n            odds = req["to_call"] / max(req["pot"] + req["to_call"], 1)\n            label = "call" if eq > odds else "fold"\n            stats.level("river", "allin_rule")\n            stats.river[f"allin_rule_{label}"] = stats.river.get(f"allin_rule_{label}", 0) + 1\n            return {"type": "action", "action": label}, label, node["id"]\n        budget = tm.river_budget_ms(req, hs.hand_id)\n        if budget <= 0:\n            stats.river["solver_skipped"] = stats.river.get("solver_skipped", 0) + 1\n            return None\n        ctx = river_api.RiverContext(\n            hand_id=hs.hand_id, seat="button" if hs.seat == 0 else "big_blind", board=list(board[:5]),\n            hole=list(hs.hole), my_discard=hs.my_discard, opp_discard=hs.opp_discard, pot=req["pot"],\n            my_bet=req["my_bet"], opp_bet=req["opp_bet"], to_call=req["to_call"], my_stack=req["my_stack"],\n            opp_stack=req["opp_stack"], legal_actions=list(legal), min_raise=req.get("min_raise"),\n            max_raise=req.get("max_raise"), raises_left=req["raises_left"],\n            pot_at_river_start=rep.pot_start["river"],\n            river_history=[dict(e) for e in req["history"] if isinstance(e, dict) and e.get("street") == "river"],\n            my_range=rr.our.copy(), opp_range=rr.opp.copy(), time_budget_ms=float(budget),\n            blueprint_dist=dict(blueprint), opp_model=self.opp_model())\n        t0 = now_ms()\n        try:\n            out = river_api.decide(ctx)\n        except Exception:\n            out = None\n            stats.river["solver_errors"] = stats.river.get("solver_errors", 0) + 1\n        dt = now_ms() - t0\n        tm.note_solver(dt, budget)\n        if dt > budget:\n            stats.river["solver_over_budget"] = stats.river.get("solver_over_budget", 0) + 1\n        dist, options = self.solver_dist(out, req)\n        if dist is None:\n            key = "solver_none" if out is None else "solver_invalid"\n            stats.river[key] = stats.river.get(key, 0) + 1\n            return None\n        dctx = DecisionContext(street="river", request=req, node_id=node["id"], options=options, pc=None,\n                               pagg=rep.pagg, fagg=rep.fagg, my_discard=hs.my_discard, opp_discard=hs.opp_discard,\n                               opp_range=rr.opp, our_range=rr.our, mode=NORMAL, source="river_solver")\n        dist = guard.apply(hooks.exploit_adjust, dctx, dist)\n        label = self.sample(dist, self.sample_key(hs, "river", len(req["history"])))\n        stats.level("river", "solver")\n        return options[label], label, node["id"]\n\n    @staticmethod\n    def opp_model():\n        try:\n            m = hooks.opp_model()\n            return m if isinstance(m, dict) else None\n        except Exception:\n            return None\n\n    @staticmethod\n    def solver_dist(out, req):\n        """Validate a river-solver distribution (§10) -> ({label: p}, {label: action}) or (None, None)."""\n        if not isinstance(out, list) or not out:\n            return None, None\n        legal = req["legal_actions"]\n        dist, options = {}, {}\n        for e in out:\n            if not isinstance(e, dict):\n                continue\n            a, p = e.get("action"), e.get("p")\n            if a not in legal or isinstance(p, bool) or not isinstance(p, numbers.Real):\n                continue\n            p = float(p)\n            if not math.isfinite(p) or p <= 0:\n                continue\n            if a == "raise":\n                amt = e.get("amount")\n                if isinstance(amt, bool) or not isinstance(amt, numbers.Integral):\n                    continue\n                amt = int(amt)\n                if not req["min_raise"] <= amt <= req["max_raise"]:\n                    continue\n                label = f"raise:{amt}"\n                options[label] = {"type": "action", "action": "raise", "amount": amt}\n            else:\n                label = a\n                options[label] = {"type": "action", "action": a}\n            dist[label] = dist.get(label, 0.0) + p\n        total = sum(dist.values())\n        if total <= 0:\n            return None, None\n        return {k: v / total for k, v in dist.items()}, options\n\n    def decide_discard(self, hs, req, fagg, guard, stats):\n        hole3 = sorted(C.parse_cards(req["hole_cards"]))\n        if hole3 != hs.hole3:\n            raise ValueError("discard_request hole cards differ from new_hand")\n        board = C.parse_cards(req["board"])\n        fi = self.flop_info(hs, board)\n        pc = B.pot_class(req["pot"])\n        cands = self.disc_candidates(fi["b3"], pc, fagg, hs.seat)\n        row, level = self.first_usable("DISC", cands, DISC_NODE, [True, True, True])\n        if row is None:\n            stats.level("discard", "heuristic")\n            dist = {"keep0": 1.0}\n        else:\n            stats.level("discard", level)\n            dist = purify({f"keep{k}": float(p) for k, p in enumerate(row) if p > 0})\n        options = {}\n        for k, pair in enumerate(fi["slots"]):\n            options[f"keep{k}"] = C.format_card(next(c for c in hs.hole3 if c not in pair))\n        ctx = DecisionContext(street="discard", request=req, node_id=0, options=options, bucket=fi["b3"],\n                              prefix_key=("DISC", cands[0][1]), pc=pc, fagg=fagg, mode=None, source="discard")\n        dist = guard.apply(hooks.exploit_adjust, ctx, dist)\n        label = self.sample(dist, self.sample_key(hs, "discard", 0))\n        k = int(label[-1])\n        return options[label], k\n\n    @staticmethod\n    def sample_key(hs, street, index):\n        """Integers only: str hashes are salted per process, int tuples hash the same everywhere."""\n        return (hs.deal, hs.seat, SAMPLE_STREET.get(street, 9), int(index))\n\n    def draw(self, key=None):\n        seed = self.config.get("sample_seed")\n        if seed is None or key is None:\n            return self.rng.random()\n        return random.Random(hash((int(seed),) + tuple(int(k) for k in key))).random()\n\n    def sample(self, dist, key=None):\n        labels = [k for k, v in dist.items() if v > 0]\n        u = self.draw(key) * sum(dist[k] for k in labels)\n        acc = 0.0\n        for k in labels:\n            acc += dist[k]\n            if u < acc:\n                return k\n        return labels[-1]\n\n    @staticmethod\n    def action_for(slot, amounts, req):\n        action = B.SLOT_ACTION[slot]\n        if action != "raise":\n            return {"type": "action", "action": action}\n        amt = int(min(max(amounts[slot], req["min_raise"]), req["max_raise"]))\n        return {"type": "action", "action": "raise", "amount": amt}\n\n    @staticmethod\n    def heuristic(node, req, opts, proxy):\n        """§9.10 level 3: OPEN -> check; FACING -> call if the equity proxy beats the pot odds."""\n        legal = {s for s, ok, _ in opts if ok}\n        if "check" in legal:\n            return "check"\n        to_call, pot = req["to_call"], req["pot"]\n        if proxy is None:                                   # preflop: the §9.2 rule\n            good = to_call <= pot / 4\n        else:\n            good = proxy > to_call / max(pot + to_call, 1)\n        if good and "call" in legal:\n            return "call"\n        return "fold" if "fold" in legal else next(iter(legal))\n\n    def panic_action(self, hs, req, street, board):\n        """§9.8 PANIC: one no-lookahead all-hands pass gives our percentile; bet pot if top 15%,\n        call if top 50% and to_call <= pot/2, else check or fold."""\n        S1, _ = F.all_features(F.street_rows(board, False))\n        live = ~np.isin(C.COMBO, board).any(axis=1)\n        mine = max(int(S1[C.idx2(*p)]) for p in (F.hand_pairs(hs.hole3) if len(hs.hole) == 3 else [tuple(hs.hole)]))\n        pct = float((S1[live] < mine).mean())\n        legal = req["legal_actions"]\n        if pct >= 0.85 and "raise" in legal:\n            target = req["opp_bet"] + req["pot"] + req["to_call"] if req["to_call"] > 0 else req["pot"]\n            return {"type": "action", "action": "raise",\n                    "amount": int(min(max(target, req["min_raise"]), req["max_raise"]))}\n        if pct >= 0.5 and "call" in legal and req["to_call"] <= req["pot"] / 2:\n            return {"type": "action", "action": "call"}\n        return {"type": "action", "action": "check" if "check" in legal else "fold"}\n'),
    'botsrc.river_api': (False, '# botsrc/river_api.py — shared contract, both of you code against it\nfrom dataclasses import dataclass\nimport numpy as np\n\n@dataclass\nclass RiverContext:\n    hand_id: int\n    seat: str                    # "button" | "big_blind"\n    board: list                  # 5 card ids (§4.1)\n    hole: list                   # our 2 kept cards\n    my_discard: int\n    opp_discard: int\n    pot: int                     # protocol fields from the current action_request\n    my_bet: int\n    opp_bet: int\n    to_call: int\n    my_stack: int\n    opp_stack: int\n    legal_actions: list\n    min_raise: int | None\n    max_raise: int | None\n    raises_left: int\n    pot_at_river_start: int\n    river_history: list          # river actions so far, protocol format\n    my_range: np.ndarray         # float64[1326], idx2 order: opponent\'s view of us at river START\n    opp_range: np.ndarray        # float64[1326]: our view of the opponent at river START\n    time_budget_ms: float        # hard budget for this call\n    blueprint_dist: dict         # our RIVER-table distribution over legal slots (fallback / warm start)\n    opp_model: dict | None       # opponent summary from the exploit layer (hooks.opp_model()), or None\n\ndef decide(ctx: RiverContext) -> list | None:\n    """Return a distribution over legal actions, e.g.\n    [{"action": "call", "amount": None, "p": 0.7}, {"action": "raise", "amount": 40, "p": 0.3}],\n    or None to use the blueprint. "amount" is the raise-to total for "raise", else None.\n    Anytime: a usable answer within 50 ms, better answers with more of ctx.time_budget_ms,\n    never past ctx.time_budget_ms. May cache per hand_id."""\n    # Phase 7: river_stub always returns None (use the blueprint). Phase 10 swaps in the solver.\n    try:\n        from . import river_stub\n    except ImportError:          # imported as a top-level module (the river kit): no stub, no solver\n        return None\n    return river_stub.decide(ctx)\n'),
    'botsrc.river_stub': (False, '"""Stand-in river solver (BUILDMAP §7 Phase 7): always defers to the blueprint.\n\nbotsrc/river_api.decide() calls decide() here. Phase 10 replaces this module with the teammate\'s\nsolver (same signature: decide(ctx: RiverContext) -> list | None).\n"""\n\n\ndef decide(ctx):\n    return None\n'),
    'botsrc.main': (False, '"""The bot\'s protocol loop (BUILDMAP §9.1, §9.2). Entry point: run(blob_b64, version) from dist/bot.py.\n\nNever crashes: every message is handled inside try/except; requests always get a legal reply\n(fallback action / discard on any error); only protocol JSON reaches stdout.\n"""\nimport json\nimport sys\n\nfrom shared import blob as BL\nfrom shared import cards as C\nfrom shared import features as F\nfrom shared import infoset as I\n\nfrom . import hooks\nfrom . import protocol as P\nfrom .log import log\nfrom .policy import ExploitGuard, Policy\nfrom .state import HandState, replay\nfrom .timeman import TimeManager, now_ms\n\nSTREET_ORDER = ("preflop", "flop", "turn", "river", "discard")\n\n\nclass Stats:\n    def __init__(self):\n        self.decisions = {s: 0 for s in STREET_ORDER}\n        self.levels = {s: {} for s in STREET_ORDER}\n        self.river = {}\n        self.errors = 0\n        self.error_kinds = {}\n        self.fallback_replies = 0\n\n    def level(self, street, level):\n        self.decisions[street] += 1\n        d = self.levels[street]\n        d[level] = d.get(level, 0) + 1\n\n    def error(self, where, exc):\n        self.errors += 1\n        key = f"{where}: {type(exc).__name__}"\n        self.error_kinds[key] = self.error_kinds.get(key, 0) + 1\n        if self.error_kinds[key] <= 3:\n            log(f"error in {where}: {type(exc).__name__}: {exc}")\n\n    def summary(self):\n        parts = []\n        for s in STREET_ORDER:\n            n = self.decisions[s]\n            lv = self.levels[s]\n            fb = {k: v for k, v in lv.items() if k != "table"}\n            share = " ".join(f"{k} {100.0 * v / n:.2f}%" for k, v in sorted(fb.items())) if n else ""\n            parts.append(f"{s} {n}" + (f" [{share}]" if share else ""))\n        return "decisions (fallback levels as % of decisions): " + "; ".join(parts)\n\n\nclass Bot:\n    def __init__(self, blob_b64, version, config=None):\n        t0 = now_ms()\n        header, arrays = BL.decode_blob(blob_b64)\n        meta = header["meta"]\n        th = F.Thresholds.from_json_bytes(arrays["THRESHOLDS"].tobytes(), expect_sha=meta["thresholds_sha"])\n        tables = {}\n        for t in I.TABLES:\n            a = arrays[t]\n            if a.shape != (I.PREFIXES[t], I.SLOTS[t]):\n                raise ValueError(f"strategy table {t} has shape {a.shape}")\n            tables[t] = a\n        canon3 = arrays["CANON3"]\n        if canon3.shape != (22100,):\n            raise ValueError("CANON3 has the wrong shape")\n        self.config = dict(config or {})\n        self.policy = Policy(tables, th, canon3, self.config)\n        self.decode_ms = now_ms() - t0\n        self.speed_factor = self.calibrate()\n        self.tm = TimeManager(self.speed_factor)\n        self.guard = ExploitGuard()\n        self.stats = Stats()\n        self.version = version\n        self.total_hands = 400\n        self.hs = None\n        self.startup_ms = now_ms() - t0\n        import numpy\n        log(f"bot ready: numpy {numpy.__version__}; {json.dumps(version, sort_keys=True)}; strategy {meta.get(\'mode\')} from "\n            f"{meta.get(\'source\')}; config {self.config}; decode {self.decode_ms:.0f} ms, start-up {self.startup_ms:.0f} ms, "\n            f"speed factor {self.speed_factor:.2f}")\n\n    @staticmethod\n    def calibrate():\n        """speed_factor = one turn street_rows pass in ms / REF_MS (the M4 reference), §9.1.\n        Median of three passes after a warm-up, so one slow pass does not skew it."""\n        from .timeman import REF_MS\n        board = [0, 13, 26, 39]\n        F.street_rows(board, True)                      # warm-up\n        times = []\n        for _ in range(3):\n            t0 = now_ms()\n            F.street_rows(board, True)\n            times.append(now_ms() - t0)\n        return min(20.0, max(0.25, sorted(times)[1] / REF_MS))\n\n    # ---------------- messages\n\n    def handle(self, msg):\n        t = msg.get("type")\n        reply = None\n        if t == "action_request":\n            reply = self.on_action(msg)\n        elif t == "discard_request":\n            reply = self.on_discard(msg)\n        else:\n            try:\n                if t == "init":\n                    self.total_hands = int(msg.get("total_hands", 400))\n                    self.tm.set_match(self.total_hands, msg.get("per_response_ms", 5000), msg.get("time_bank_ms"))\n                elif t == "new_hand":\n                    self.hs = None\n                    self.tm.begin_hand(msg.get("hand_id"))\n                    self.hs = HandState(msg, mirror=self.policy.mirror)\n                elif t == "discard_result" and self.hs is not None:\n                    self.hs.on_discard_result(msg)\n                elif t == "notice" and self.hs is not None:\n                    self.hs.on_notice(msg)\n                elif t == "match_end":\n                    self.finish()\n            except Exception as e:\n                self.stats.error(t or "message", e)\n        self.forward(msg)\n        return reply\n\n    def forward(self, msg):\n        if self.guard.disabled:\n            return\n        t0 = now_ms()\n        try:\n            hooks.on_event(msg)\n        except Exception:\n            self.guard.errors += 1\n        self.guard.charge(now_ms() - t0)\n\n    def on_action(self, req):\n        t0 = now_ms()\n        self.tm.observe(req)\n        street = req.get("street") if isinstance(req.get("street"), str) else "?"\n        counted = self.stats.decisions.get(street)\n        self.tm.begin_decision()\n        reply = None\n        try:\n            hs = self.hs\n            if hs is None or req.get("hand_id") != hs.hand_id:\n                raise ValueError("action_request for an unknown hand")\n            rep = replay(hs, req["history"])\n            if rep.error is not None or rep.lost:\n                raise ValueError(f"history replay: {rep.error or \'action off the tree\'}")\n            if rep.current_street != street or rep.current_node is None or rep.current_node < 0 \\\n                    or rep.current_state is None or rep.current_state.actor != hs.seat:\n                raise ValueError("history does not lead to our decision on this street")\n            mode = self.tm.mode(req, hs.hand_id, self.total_hands)\n            reply, slot, node_id = self.policy.decide_action(hs, req, rep, mode, self.guard, self.stats, self.tm)\n            if not P.legal_reply(reply, req):\n                raise ValueError(f"policy produced an illegal reply {reply}")\n            hs.record_own(req, reply, node_id, slot)\n        except Exception as e:\n            self.stats.error(f"action/{street}", e)\n            self.stats.fallback_replies += 1\n            if counted is not None and self.stats.decisions[street] == counted:\n                self.stats.level(street, "error")\n            reply = P.fallback_action(req)\n            try:\n                if self.hs is not None:\n                    self.hs.record_own(req, reply, None, None)\n            except Exception:\n                pass\n        total = now_ms() - t0\n        dec = self.tm.dec\n        self.tm.add(own_ms=total - dec["range"] - dec["solver"], range_ms=dec["range"], solver_ms=dec["solver"],\n                    river_decision=street == "river")\n        self.tm.record(street, total)\n        self.tm.replied(now_ms() - t0)\n        return reply\n\n    def on_discard(self, req):\n        t0 = now_ms()\n        self.tm.observe(req)\n        counted = self.stats.decisions["discard"]\n        reply = None\n        try:\n            hs = self.hs\n            if hs is None or req.get("hand_id") != hs.hand_id:\n                raise ValueError("discard_request for an unknown hand")\n            rep = replay(hs, hs.history_after)\n            fagg = rep.fagg if rep.error is None else 0\n            card, k = self.policy.decide_discard(hs, req, fagg, self.guard, self.stats)\n            if card not in req["hole_cards"]:\n                raise ValueError("discard is not one of our hole cards")\n            hs.keep_slot = k\n            reply = {"type": "discard", "card": card}\n        except Exception as e:\n            self.stats.error("discard", e)\n            self.stats.fallback_replies += 1\n            if self.stats.decisions["discard"] == counted:\n                self.stats.level("discard", "error")\n            reply = self.fallback_discard(req)\n        total = now_ms() - t0\n        self.tm.add(own_ms=total)\n        self.tm.record("discard", total)\n        self.tm.replied(now_ms() - t0)\n        return reply\n\n    def fallback_discard(self, req):\n        """§9.2: keep slot 0 if the flop features exist, else the engine\'s own default card."""\n        hole = req.get("hole_cards") if isinstance(req, dict) else None\n        try:\n            hs = self.hs\n            fi = self.policy.flop_info(hs, C.parse_cards(req["board"]))\n            card = C.format_card(next(c for c in hs.hole3 if c not in fi["slots"][0]))\n            if card in hole:\n                return {"type": "discard", "card": card}\n        except Exception:\n            pass\n        card = P.default_discard(hole)\n        return {"type": "discard", "card": card if card is not None else ""}\n\n    def emergency(self, msg):\n        """Last resort if handle() itself raised: a legal-looking reply for requests, else nothing."""\n        t = msg.get("type") if isinstance(msg, dict) else None\n        if t == "action_request":\n            return P.fallback_action(msg)\n        if t == "discard_request":\n            card = P.default_discard(msg.get("hole_cards"))\n            return {"type": "discard", "card": card if card is not None else ""}\n        return None\n\n    def finish(self):\n        if getattr(self, "_finished", False):\n            return\n        self._finished = True\n        tm = self.tm\n        per = "; ".join(f"{s} {tm.street_ms[s] / tm.street_n[s]:.1f} ms x {tm.street_n[s]}"\n                        for s in STREET_ORDER if tm.street_n.get(s))\n        log(self.stats.summary())\n        log(f"time: {tm.summary()}")\n        log(f"river: {self.stats.river}")\n        log(f"fallbacks: {self.stats.fallback_replies} fallback replies, {self.stats.errors} errors "\n            f"{self.stats.error_kinds}; modes {tm.modes}; time per decision: {per}")\n        g = self.guard\n        log(f"exploit hook: {g.calls} calls, {g.total_ms:.1f} ms, {g.over} over {5} ms, {g.errors} errors, "\n            f"{g.capped} capped, disabled {g.disabled}")\n        if log.dropped:\n            log(f"log: {log.dropped} lines dropped at the {log.limit} byte cap")\n\n\nclass FallbackBot:\n    """Used only if the strategy could not be loaded: plays the §9.2 fallback, never crashes."""\n\n    def __init__(self, error):\n        self.stats = Stats()\n        banner = "!" * 78\n        log(f"{banner}\\nDHBOT DEGRADED: the strategy failed to load ({type(error).__name__}: {error})\\n"\n            f"Playing fallback actions only: this match does NOT use the strategy.\\n{banner}")\n\n    def handle(self, msg):\n        t = msg.get("type")\n        if t == "action_request":\n            return P.fallback_action(msg)\n        if t == "discard_request":\n            card = P.default_discard(msg.get("hole_cards"))\n            return {"type": "discard", "card": card if card is not None else ""}\n        return None\n\n    def emergency(self, msg):\n        return self.handle(msg)\n\n    def finish(self):\n        pass\n\n\ndef run(blob_b64, version, config=None):\n    out = sys.stdout\n    sys.stdout = sys.stderr                     # nothing but protocol replies reaches the real stdout\n    try:\n        bot = Bot(blob_b64, version, config)\n    except Exception as e:\n        bot = FallbackBot(e)\n    for raw in sys.stdin:\n        line = raw.strip()\n        if not line:\n            continue\n        try:\n            msg = json.loads(line)\n        except Exception:\n            continue\n        if not isinstance(msg, dict):\n            continue\n        try:\n            reply = bot.handle(msg)\n        except Exception:\n            reply = bot.emergency(msg)\n        if reply is not None:\n            try:\n                out.write(json.dumps(reply) + "\\n")\n                out.flush()\n            except Exception:\n                pass\n        if msg.get("type") == "match_end":\n            break\n    try:\n        bot.finish()\n    except Exception:\n        pass\n'),
}


class _BundleFinder(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    """Imports shared.* and botsrc.* from _SOURCES (never from the file system)."""

    def find_spec(self, fullname, path=None, target=None):
        if fullname in _SOURCES:
            return importlib.util.spec_from_loader(fullname, self, is_package=_SOURCES[fullname][0])
        return None

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        source = _SOURCES[module.__name__][1]
        exec(compile(source, "<bot.py:" + module.__name__ + ">", "exec"), module.__dict__)


